178	/* Visible span in samples for the current zoom */
179	
180	static uint32_t scope_span(void)
181	{
182	  return (SCOPE_POINT_CNT * 256 + g_ui.zoom / 2) / g_ui.zoom;
183	}
184	
185	/* Apply the current zoom/pan window to every series of both charts.
186	 * Window end is anchored at the frozen cursor; pan moves it back. */
187	
188	static void scope_apply_view(void)
189	{
190	  uint32_t span = scope_span();
191	  uint32_t maxpan = SCOPE_POINT_CNT - span;
192	  uint32_t pan = g_ui.pan;
193	  uint32_t start;
194	
195	  if (pan > maxpan)
196	    {
197	      pan = maxpan;
198	      g_ui.pan = pan;
199	    }
200	
201	  start = (g_ui.cursor + SCOPE_POINT_CNT - span - pan) % SCOPE_POINT_CNT;
202	
203	  /* Per-series: every series of every chart sharing the time base */
204	
205	  lv_chart_set_x_start_point(g_ui.chart_cur, g_ui.ser_id, start);
206	  lv_chart_set_x_start_point(g_ui.chart_cur, g_ui.ser_iq, start);
207	  lv_chart_set_x_start_point(g_ui.chart_rpm, g_ui.ser_rpm, start);
208	}
