224	    g_ui.btn_left, g_ui.btn_right, g_ui.btn_clear
225	  };
226	  int i;
227	
228	  for (i = 0; i < (int)(sizeof(btns) / sizeof(btns[0])); i++)
229	    {
230	      if (en)
231	        {
232	          lv_obj_clear_state(btns[i], LV_STATE_DISABLED);
233	        }
234	      else
235	        {
236	          lv_obj_add_state(btns[i], LV_STATE_DISABLED);
237	        }
238	    }
239	}
