260	
261	      g_ui.cursor = lv_chart_get_x_start_point(g_ui.chart_cur, g_ui.ser_id);
262	      g_ui.pan = 0;
263	      scope_apply_view();
264	      lv_label_set_text(g_ui.lb_state, "PAUSED");
265	      lv_obj_set_style_text_color(g_ui.lb_state, CLR_PAUSED, 0);
266	      lv_label_set_text(g_ui.lab_pause, "RUN");
267	    }
268	
269	  scope_set_view_btns_enabled(state == SCOPE_STATE_PAUSED);
