272	/* --- button actions --- */
273	
274	static void scope_act_zoom(int dir)
275	{
276	  int i;
277	  int idx = -1;
278	
279	  for (i = 0; i < (int)ZOOM_TABLE_LEN; i++)
280	    {
281	      if (g_zoom_table[i] == g_ui.zoom)
282	        {
283	          idx = i;
284	          break;
285	        }
286	    }
287	
288	  if (idx < 0)
289	    {
290	      idx = 0;
291	    }
292	
293	  idx += dir;
294	  if (idx < 0 || idx >= (int)ZOOM_TABLE_LEN)
295	    {
296	      return;
297	    }
298	
299	  scope_set_zoom(g_zoom_table[idx]);
300	  scope_apply_view();
301	}
302	
303	static void scope_act_pan(int dir)
304	{
305	  uint32_t span = scope_span();
306	  uint32_t maxpan = SCOPE_POINT_CNT - span;
307	  uint32_t step = (maxpan + 7) / 8;
308	
309	  if (step < 1)
310	    {
311	      step = 1;
312	    }
313	
314	  if (dir > 0)
315	    {
316	      /* pan further back into history */
317	
318	      if (g_ui.pan < maxpan)
319	        {
320	          g_ui.pan = g_ui.pan + step;
321	          if (g_ui.pan > maxpan)
322	            {
323	              g_ui.pan = maxpan;
324	            }
325	
326	          scope_apply_view();
327	        }
328	    }
329	  else
330	    {
331	      /* pan back toward the cursor */
332	
333	      if (g_ui.pan >= step)
334	        {
335	          g_ui.pan -= step;
336	        }
337	      else if (g_ui.pan > 0)
338	        {
339	          g_ui.pan = 0;
340	        }
341	
342	      scope_apply_view();
343	    }
344	}
