377	static void scope_btn_cb(lv_event_t *e)
378	{
379	  int act = (int)(intptr_t)lv_event_get_user_data(e);
380	
381	  switch (act)
382	    {
383	      case ACT_PAUSE:
384	        scope_set_state(g_ui.state == SCOPE_STATE_RUN ?
385	                        SCOPE_STATE_PAUSED : SCOPE_STATE_RUN);
386	        break;
387	
388	      case ACT_ZOOM_IN:
389	        scope_act_zoom(1);
390	        break;
391	
392	      case ACT_ZOOM_OUT:
393	        scope_act_zoom(-1);
394	        break;
395	
396	      case ACT_SCALE:
397	        scope_act_scale();
398	        break;
399	
400	      case ACT_CLEAR:
401	        scope_act_clear();
402	        break;
403	
404	      case ACT_LEFT:
405	        scope_act_pan(1);
406	        break;
407	
408	      case ACT_RIGHT:
409	        scope_act_pan(-1);
410	        break;
411	
412	      case ACT_CH:
413	        scope_act_channel();
414	        break;
415	
416	      default:
417	        break;
418	    }
419	}
