422	
423	static void scope_push_sample(FAR scope_sample_t *s)
424	{
425	  lv_chart_set_next_value(g_ui.chart_cur, g_ui.ser_id,
426	                          (int32_t)(s->id * 1000.0f));
427	  lv_chart_set_next_value(g_ui.chart_cur, g_ui.ser_iq,
428	                          (int32_t)(s->iq * 1000.0f));
429	  lv_chart_set_next_value(g_ui.chart_rpm, g_ui.ser_rpm,
430	                          (int32_t)s->speed);
431	}
432	
433	static void scope_timer_cb(lv_timer_t *timer)
434	{
435	  scope_sample_t s;
436	  int k;
437	
438	  if (g_ui.state == SCOPE_STATE_RUN)
439	    {
440	      for (k = 0; k < SCOPE_SAMPLES_PER_TICK; k++)
441	        {
442	          if (g_ui.ds->get_sample(g_ui.ds, &s) < 0)
443	            {
444	              break;
445	            }
446	
447	          scope_push_sample(&s);
448	          g_ui.last = s;
449	        }
450	    }
451	
452	  /* Readouts refresh every tick (cheap: only the label area redraws) */
453	
454	  lv_label_set_text_fmt(g_ui.lb_id,   "id  %+.2fA", g_ui.last.id);
455	  lv_label_set_text_fmt(g_ui.lb_iq,   "iq  %+.2fA", g_ui.last.iq);
456	  lv_label_set_text_fmt(g_ui.lb_rpm,  "rpm %.0f",   g_ui.last.speed);
457	  lv_label_set_text_fmt(g_ui.lb_vbus, "Vb  %.1fV",  g_ui.last.vbus);
458	}
