158	    LV_LOG_USER("Resolution is set to %dx%d at %" LV_PRId32 "dpi",
159	                dsc->vinfo.xres, dsc->vinfo.yres, lv_display_get_dpi(disp));
160	    return 0;
161	
162	errout:
163	    close(dsc->fd);
164	    dsc->fd = -1;
165	    return ret;
