static uint32_t refr_cnt; /* FOCPilot: periodic refr heartbeat log */

static void display_refr_timer_cb(lv_timer_t * tmr)
{
    lv_display_t * disp = lv_timer_get_user_data(tmr);

    /* FOCPilot fix: the original code gated redraw behind poll(POLLOUT)
     * on the fb fd. NuttX's poll() re-registers every call, but LVGL
     * passes a fresh pollfd each time, so the driver's poll slots (only
     * CONFIG_VIDEO_FB_NPOLLWAITERS of them) leak one entry per call and
     * the third call fails with -EBUSY, after which LVGL never redraws.
     * The SPI LCD has no hardware panning, so the gate has no purpose
     * here - redraw unconditionally. */

    _lv_display_refr_timer(tmr);

    /* Heartbeat: log every 500th redraw (~15s at 30ms period) so a boot
     * log can prove redraw is actually running. */

    if((++refr_cnt % 500) == 1) {
        LV_LOG_WARN("fbdev refr heartbeat %u", refr_cnt);
    }
}

