536	static void sw_rgb565_swap(void * buf, uint32_t buf_size_px)
537	{
538	    uint32_t u32_cnt = buf_size_px / 2;
539	    uint16_t * buf16 = buf;
540	    uint32_t * buf32 = buf;
541	
542	    while(u32_cnt >= 8) {
543	        buf32[0] = ((buf32[0] & 0xff00ff00) >> 8) | ((buf32[0] & 0x00ff00ff) << 8);
544	        buf32[1] = ((buf32[1] & 0xff00ff00) >> 8) | ((buf32[1] & 0x00ff00ff) << 8);
545	        buf32[2] = ((buf32[2] & 0xff00ff00) >> 8) | ((buf32[2] & 0x00ff00ff) << 8);
546	        buf32[3] = ((buf32[3] & 0xff00ff00) >> 8) | ((buf32[3] & 0x00ff00ff) << 8);
547	        buf32[4] = ((buf32[4] & 0xff00ff00) >> 8) | ((buf32[4] & 0x00ff00ff) << 8);
548	        buf32[5] = ((buf32[5] & 0xff00ff00) >> 8) | ((buf32[5] & 0x00ff00ff) << 8);
549	        buf32[6] = ((buf32[6] & 0xff00ff00) >> 8) | ((buf32[6] & 0x00ff00ff) << 8);
550	        buf32[7] = ((buf32[7] & 0xff00ff00) >> 8) | ((buf32[7] & 0x00ff00ff) << 8);
551	        buf32 += 8;
552	        u32_cnt -= 8;
553	    }
554	
555	    while(u32_cnt) {
556	        *buf32 = ((*buf32 & 0xff00ff00) >> 8) | ((*buf32 & 0x00ff00ff) << 8);
557	        buf32++;
558	        u32_cnt--;
559	    }
560	
561	    if(buf_size_px & 0x1) {
562	        uint32_t e = buf_size_px - 1;
563	        buf16[e] = ((buf16[e] & 0xff00) >> 8) | ((buf16[e] & 0x00ff) << 8);
564	    }
565	
566	}
567	static int spi_lcd_updatearea(struct fb_vtable_s *vtable, FAR const struct fb_area_s *area)
568	{
569	  struct spi_dev_s *spi = g_spi_lcd_fb->spi;
570	  int stride = g_spi_lcd_fb->planeinfo.stride;
571	  int width_byte = area->w * (g_spi_lcd_fb->planeinfo.bpp >> 3);
572	  unsigned char *fb = g_spi_lcd_fb->planeinfo.fbmem + area->y * stride + area->x * (g_spi_lcd_fb->planeinfo.bpp >> 3);
573	
574	  static uint8_t *swapped_datas;
575	
576	  if (!swapped_datas)
577	  {
578	    swapped_datas = malloc(stride);
579	  }
580	
581	  LCD_SetWindows(area->x, area->y, area->x + area->w - 1, area->y + area->h - 1);
582	  lcd_lock();
583	  LCD_SetDataLine();
584	  SPI_SELECT(spi, 0, true);
585	  for (int y = area->y; y < area->y + area->h; y++)
586	  {
587	    memcpy(swapped_datas, fb, width_byte);
588	    sw_rgb565_swap(swapped_datas, area->w);
589	    SPI_SNDBLOCK(spi, swapped_datas, width_byte);
590	    fb += stride;
591	  }
592	  SPI_SELECT(spi, 0, false);
593	  lcd_unlock();
594	  return 0;
595	}
