206	static void sunxi_spi_setmode(struct spi_dev_s *dev,
207	                              enum spi_mode_e mode)
208	{
209	  struct sunxi_spi_priv_s *priv = (struct sunxi_spi_priv_s *)dev;
210	
211	  spiinfo("mode=%d\n", mode);
212	
213	  /* Has the mode changed? */
214		if (mode != priv->mode)
215	    {
216	      switch (mode)
217	        {
218	        case SPIDEV_MODE0: /* CPOL=0; CPHA=0 */
219	          priv->spim.cfg.cpha = HAL_SPI_MASTER_CLOCK_PHASE0;
220	          priv->spim.cfg.cpol = HAL_SPI_MASTER_CLOCK_POLARITY0;
221	          break;
222	
223	        case SPIDEV_MODE1: /* CPOL=0; CPHA=1 */
224	          priv->spim.cfg.cpha = HAL_SPI_MASTER_CLOCK_PHASE1;
225	          priv->spim.cfg.cpol = HAL_SPI_MASTER_CLOCK_POLARITY0;
226	          break;
227	
228	        case SPIDEV_MODE2: /* CPOL=1; CPHA=0 */
229	          priv->spim.cfg.cpha = HAL_SPI_MASTER_CLOCK_PHASE0;
230	          priv->spim.cfg.cpol = HAL_SPI_MASTER_CLOCK_POLARITY1;
231	          break;
232	
233	        case SPIDEV_MODE3: /* CPOL=1; CPHA=1 */
234	          priv->spim.cfg.cpha = HAL_SPI_MASTER_CLOCK_PHASE1;
235	          priv->spim.cfg.cpol = HAL_SPI_MASTER_CLOCK_POLARITY1;
236	          break;
237	
238	        default:
239	          return;
240	        }
241	        hal_spi_hw_config(priv->spim.port, &priv->spim.cfg);
242	    }
243	}
