278	static void sunxi_spi_exchange(struct spi_dev_s *dev,
279	                               const void *txbuffer,
280	                               void *rxbuffer,
281	                               size_t nwords)
282	{
283	  struct sunxi_spi_priv_s *priv = (struct sunxi_spi_priv_s *)dev;
284	
285		hal_spi_master_transfer_t tr;
286	
287		memset(&tr, 0, sizeof(tr));
288	
289		tr.tx_buf = (uint8_t *)txbuffer;
290		tr.rx_buf = rxbuffer;
291		tr.tx_len = nwords;
292		tr.rx_len = nwords;
293	    tr.rx_nbits = tr.tx_nbits = priv->nbits;
294		tr.tx_single_len = nwords;
295		tr.dummy_byte = 0;
296	
297		hal_spi_xfer(priv->spim.port, &tr);
298	}
