77	static uint8_t* read_all_from_file(const char* path)
78	{
79	    int fd = 0;
80	    int flen = 0;
81	    uint8_t* content = NULL;
82	
83	    fd = open(path, O_RDONLY);
84	
85	    if (fd < 0) {
86	        fprintf(stderr, "ERROR(showlogo): file :%s open failed! errno is %d\n", path, errno);
87	        return NULL;
88	    }
89	
90	    flen = lseek(fd, 0L, SEEK_END);
91	
92	    if (flen == -1) {
93	      fprintf(stderr, "ERROR(showlogo): lseek failed: %d\n", errno);
94	      close(fd);
95	      return NULL;
96	    }
97	    lseek(fd, 0L, SEEK_SET);
98	
99	    content = malloc(flen + 1);
100	
101	    DEBUGASSERT(content != NULL);
102	
103	    if (content) {
104	        if (read(fd, content, flen) == -1) {
105	            fprintf(stderr, "ERROR(showlogo): read failed: %d\n", errno);
106	            free(content);
107	            close(fd);
108	            return NULL;
109	        }
110	        content[flen] = 0;
111	    }
112	    close(fd);
113	    return content;
114	}
