116	int main(int argc, char* argv[])
117	{
118	    const char* file_path = NULL;
119	    const char* fbdev = "/dev/fb0";
120	    struct fb_handle_t handle;
121	    uint8_t* img_buffer = NULL;
122	    img_head_t* img_head = NULL;
123	    uint32_t* img_data = NULL;
124	    uint32_t* fb_bpp32 = NULL;
125	    uint32_t y = 0;
126	    uint32_t fb_offset = 0;
127	    uint32_t img_offset = 0;
128	    fb_coord_t plane_stride_bpp32 = 0;
129	    int ch;
130	
131	    while ((ch = getopt(argc, argv, "hn:f::")) != -1) {
132	        switch (ch) {
133	        case 'h':
134	            show_usage();
135	            break;
136	        case 'n':
137	            file_path = optarg;
138	            break;
139	        case 'f':
140	            fbdev = optarg;
141	            break;
142	        default:
143	            break;
144	        }
145	    }
146	
147	    if (file_path == NULL) {
148	        show_usage();
149	        return EXIT_FAILURE;
150	    }
151	
152	    /* Open the framebuffer device */
153	    handle.fb_device = open(fbdev, O_RDWR);
154	    if (handle.fb_device < 0) {
155	        fprintf(stderr, "ERROR(showlogo): Failed to open %s.\n", fbdev);
156	        return EXIT_FAILURE;
157	    }
158	
159	    /* Get the characteristics of the framebuffer */
160	    if (ioctl(handle.fb_device, FBIOGET_VIDEOINFO,
161	            (unsigned long)((uintptr_t)&handle.video_info))
162	        < 0) {
163	        fprintf(stderr, "ERROR(showlogo): ioctl(FBIOGET_VIDEOINFO) failed.\n");
164	        goto fail;
165	    }
166	
167	    if (ioctl(handle.fb_device, FBIOGET_PLANEINFO,
168	            (unsigned long)((uintptr_t)&handle.plane_info))
169	        < 0) {
170	        fprintf(stderr, "ERROR(showlogo): ioctl(FBIOGET_PLANEINFO) failed.\n");
171	        goto fail;
172	    }
173	
174	    if (handle.plane_info.bpp != 32) {
175	        fprintf(stderr, "ERROR(showlogo): bpp=%u only supported 32.\n", handle.plane_info.bpp);
176	        goto fail;
177	    }
178	
179	    handle.fb_mem = mmap(NULL, handle.plane_info.fblen, PROT_READ | PROT_WRITE,
180	        MAP_SHARED | MAP_FILE, handle.fb_device, 0);
181	    if (handle.fb_mem == MAP_FAILED) {
182	        fprintf(stderr, "ERROR(showlogo): mmap failed. errno is %d\n", errno);
183	        goto fail;
184	    }
185	
186	    img_buffer = read_all_from_file(file_path);
187	    img_head = (img_head_t*)img_buffer;
188	    if (!img_head) {
189	        fprintf(stderr, "ERROR(showlogo): no image buffer found\n");
190	        goto fail_munmap;
191	    }
192	
193	    if (img_head->cf != IMG_CF_TRUE_COLOR && img_head->cf != IMG_CF_TRUE_COLOR_ALPHA
194	        && img_head->cf != IMG_CF_TRUE_COLOR_CHROMA_KEYED && img_head->cf != IMG_CF_RGB888
195	        && img_head->cf != IMG_CF_RGBA8888 && img_head->cf != IMG_CF_RGBX8888) {
196	        fprintf(stderr, "ERROR(showlogo): color format:%u image only supported 32.\n", img_head->cf);
197	        goto fail_munmap;
198	    }
199	
200	    if (img_head->w > handle.video_info.xres || img_head->h > handle.video_info.yres) {
201	        fprintf(stderr, "ERROR(showlogo): image size exceeds Horizontal or Vertical resolution\n");
202	        goto fail_munmap;
203	    }
204	
205	    if (img_head->stride == 0 || img_head->stride > handle.plane_info.stride) {
206	        fprintf(stderr, "ERROR(showlogo): image stride invalid\n");
207	        goto fail_munmap;
208	    }
209	
210	    img_data = (uint32_t*)(img_buffer + sizeof(img_head_t));
211	
212	    fb_bpp32 = handle.fb_mem;
213	    plane_stride_bpp32 = handle.plane_info.stride / (handle.plane_info.bpp / 8.);
214	    fb_offset = (handle.video_info.xres - img_head->w) / 2
215	        + (handle.video_info.yres - img_head->h) / 2 * plane_stride_bpp32;
216	
217	    if (handle.video_info.xres > img_head->w || handle.video_info.yres > img_head->h) {
218	        memset(fb_bpp32, 0, handle.plane_info.fblen);
219	    }
220	
221	    for (y = 0; y < img_head->h; y++) {
222	        memcpy(fb_bpp32 + fb_offset, img_data + img_offset, img_head->stride);
223	        fb_offset += plane_stride_bpp32;
224	        img_offset += img_head->w;
225	    }
226	
227	#if defined(CONFIG_FB_UPDATE)
228	    struct fb_area_s fb_area;
229	    fb_area.x = 0;
230	    fb_area.y = 0;
231	    fb_area.w = handle.video_info.xres;
232	    fb_area.h = handle.video_info.yres;
233	
234	    if (ioctl(handle.fb_device, FBIO_UPDATE, (unsigned long)((uintptr_t)&fb_area))
235	        < 0) {
236	        fprintf(stderr, "ERROR(showlogo): ioctl(FBIO_UPDATE) failed. errno code:%d.\n", errno);
237	        goto fail_munmap;
238	    }
239	#endif
240	
241	    /* Commit buffer to fb if double buffering is enabled */
242	    if(handle.plane_info.yres_virtual == (handle.video_info.yres * 2)) {
243	        if (ioctl(handle.fb_device, FBIOPAN_DISPLAY,
244	                (unsigned long)((uintptr_t)&handle.plane_info))
245	            < 0) {
246	            fprintf(stderr, "ERROR(showlogo): ioctl(FBIOPAN_DISPLAY) failed. errno code:%d.\n", errno);
247	        }
248	    }
249	
250	fail_munmap:
251	    free(img_buffer);
252	    munmap(handle.fb_mem, handle.plane_info.fblen);
253	
254	fail:
255	    close(handle.fb_device);
256	    return EXIT_SUCCESS;
257	}
