105	static bool _g2d_draw_img_supported(const lv_draw_image_dsc_t * draw_dsc, int32_t size)
106	{
107	    const lv_image_dsc_t * img_dsc = draw_dsc->src;
108	
109	    bool has_recolor = (draw_dsc->recolor_opa != LV_OPA_TRANSP);
110	    bool has_transform = (draw_dsc->rotation != 0 || draw_dsc->scale_x != LV_SCALE_NONE ||
111	                          draw_dsc->scale_y != LV_SCALE_NONE);
112	
113	    /* Recolor and transformation are not supported at the same time. */
114	    if(has_recolor && has_transform)
115	        return false;
116	
117	    bool has_opa = (draw_dsc->opa < (lv_opa_t)LV_OPA_MAX);
118	    bool src_has_alpha = (img_dsc->header.cf == LV_COLOR_FORMAT_ARGB8888);
119	
120	    /*
121	     * Recolor or transformation for images w/ opa or alpha channel can't
122	     * be obtained in a single G2D configuration. Two steps are required.
123	     */
124	
125	    if(!has_opa && !src_has_alpha  && (size < sunxifb_g2d_get_limit(SUNXI_G2D_LIMIT_BLIT)))
126	        return false;
127	
128	    if((has_opa || src_has_alpha)  && (size < sunxifb_g2d_get_limit(SUNXI_G2D_LIMIT_BLEND)))
129	        return false;
130	
131	    /* G2D can only rotate at 90x angles. */
132	    if(draw_dsc->rotation || has_recolor)
133	        return false;
134	
135	    if(((draw_dsc->scale_x != LV_SCALE_NONE) || (draw_dsc->scale_y != LV_SCALE_NONE)) &&
136	       (size < sunxifb_g2d_get_limit(SUNXI_G2D_LIMIT_SCALE)))
137	        return false;
138	
139	    /*
140	     * G2D is set to process 16x16 blocks to optimize the system for memory
141	     * bandwidth and image processing time.
142	     * The output engine essentially truncates any output pixels after the
143	     * desired number of pixels has been written.
144	     * When rotating a source image and the output is not divisible by the block
145	     * size, the incorrect pixels could be truncated and the final output image
146	     * can look shifted.
147	     *
148	     * No combination of rotate with flip, scaling or decimation is possible
149	     * if buffer is unaligned.
150	     */
151	    /*if(has_transform && (img_dsc->header.w % 16 || img_dsc->header.h % 16))
152	        return false;*/
153	    return true;
154	}
