156	static int32_t _g2d_evaluate(lv_draw_unit_t * u, lv_draw_task_t * t)
157	{
158	    LV_UNUSED(u);
159	    lv_area_t img_area;
160	    if(!_lv_area_intersect(&img_area, &t->area, &t->clip_area))
161	        return 0;
162	    int32_t size = lv_area_get_width(&img_area) * lv_area_get_height(&img_area);
163	    switch(t->type) {
164	        case LV_DRAW_TASK_TYPE_FILL: {
165	                const lv_draw_fill_dsc_t * draw_dsc = (lv_draw_fill_dsc_t *) t->draw_dsc;
166	
167	                /* Most simple case: just a plain rectangle (no radius, no gradient). */
168	                if((draw_dsc->radius != 0) || (draw_dsc->grad.dir != (lv_grad_dir_t)LV_GRAD_DIR_NONE))
169	                    return 0;
170	
171	                if((draw_dsc->opa >= LV_OPA_MAX) && (size < sunxifb_g2d_get_limit(SUNXI_G2D_LIMIT_FILL))) {
172	                    return 0;
173	                }
174	                if((draw_dsc->opa > LV_OPA_MIN) && (size < sunxifb_g2d_get_limit(SUNXI_G2D_LIMIT_OPA_FILL))) {
175	                    return 0;
176	                }
177	
178	                if(t->preference_score > 70) {
179	                    t->preference_score = 70;
180	                    t->preferred_draw_unit_id = DRAW_UNIT_ID_G2D;
181	                }
182	                return 1;
183	            }
184	
185	        case LV_DRAW_TASK_TYPE_LAYER: {
186	                const lv_draw_image_dsc_t * draw_dsc = (lv_draw_image_dsc_t *) t->draw_dsc;
187	                lv_layer_t * layer_to_draw = (lv_layer_t *)draw_dsc->src;
188	                //lv_draw_buf_t * draw_buf = &layer_to_draw->draw_buf;
189	
190	                if(!_g2d_cf_supported(layer_to_draw->color_format))
191	                    return 0;
192	
193	                if(!_g2d_draw_img_supported(draw_dsc, size))
194	                    return 0;
195	
196	                if(t->preference_score > 70) {
197	                    t->preference_score = 70;
198	                    t->preferred_draw_unit_id = DRAW_UNIT_ID_G2D;
199	                }
200	                return 1;
201	            }
202	
203	        case LV_DRAW_TASK_TYPE_IMAGE: {
204	                lv_draw_image_dsc_t * img_dsc = (lv_draw_image_dsc_t *) t->draw_dsc;
205	                if(!_g2d_cf_supported(img_dsc->header.cf))
206	                    return 0;
207	
208	                if(!_g2d_draw_img_supported(img_dsc, size))
209	                    return 0;
210	
211	                if(t->preference_score > 70) {
212	                    t->preference_score = 70;
213	                    t->preferred_draw_unit_id = DRAW_UNIT_ID_G2D;
214	                }
215	                return 1;
216	            }
217	        default:
218	            return 0;
219	    }
220	
221	    return 0;
222	}
