224	static int32_t _g2d_dispatch(lv_draw_unit_t * draw_unit, lv_layer_t * layer)
225	{
226	    lv_draw_g2d_unit_t * draw_g2d_unit = (lv_draw_g2d_unit_t *) draw_unit;
227	
228	    /* Return immediately if it's busy with draw task. */
229	    if(draw_g2d_unit->task_act)
230	        return 0;
231	
232	    /* Return if target buffer format is not supported. */
233	    if(!_g2d_cf_supported(layer->color_format))
234	        return -1;
235	
236	    /* Try to get an ready to draw. */
237	    lv_draw_task_t * t = lv_draw_get_next_available_task(layer, NULL, DRAW_UNIT_ID_G2D);
238	
239	    /* Return -1 is no selection, some tasks can be supported only by other units. */
240	    if(t == NULL || t->preferred_draw_unit_id != DRAW_UNIT_ID_G2D)
241	        return -1;
242	
243	    void * buf = lv_draw_layer_alloc_buf(layer);
244	    if(buf == NULL)
245	        return -1;
246	
247	    t->state = LV_DRAW_TASK_STATE_IN_PROGRESS;
248	    draw_g2d_unit->base_unit.target_layer = layer;
249	    draw_g2d_unit->base_unit.clip_area = &t->clip_area;
250	    draw_g2d_unit->task_act = t;
251	
252	#if LV_USE_OS
253	    /* Let the render thread work. */
254	    if(draw_g2d_unit->inited) lv_thread_sync_signal(&draw_g2d_unit->sync);
255	#else
256	    _g2d_execute_drawing(draw_g2d_unit);
257	
258	    draw_g2d_unit->task_act->state = LV_DRAW_TASK_STATE_READY;
259	    draw_g2d_unit->task_act = NULL;
260	
261	    /* The draw unit is free now. Request a new dispatching as it can get a new task. */
262	    lv_draw_dispatch_request();
263	#endif
264	
265	    return 1;
266	}
267	
268	static void _g2d_execute_drawing(lv_draw_g2d_unit_t * u)
269	{
270	    lv_draw_task_t * t = u->task_act;
271	    lv_draw_unit_t * draw_unit = (lv_draw_unit_t *)u;
272	    /* Invalidate cache */
273	    lv_layer_t * layer = draw_unit->target_layer;
274	    lv_draw_buf_t * draw_buf = layer->draw_buf;
275	    lv_area_t draw_area;
276	    if(!_lv_area_intersect(&draw_area, &t->area, draw_unit->clip_area))
277	        return; /*Fully clipped, nothing to do*/
278	    lv_draw_buf_invalidate_cache(draw_buf, &draw_area);
279	
280	    switch(t->type) {
281	        case LV_DRAW_TASK_TYPE_FILL:
282	            lv_draw_g2d_fill(draw_unit, t->draw_dsc, &t->area);
283	            break;
284	        case LV_DRAW_TASK_TYPE_IMAGE:
285	            lv_draw_g2d_img(draw_unit, t->draw_dsc, &t->area);
286	            break;
287	        case LV_DRAW_TASK_TYPE_LAYER:
288	            lv_draw_g2d_layer(draw_unit, t->draw_dsc, &t->area);
289	            break;
290	        default:
291	            break;
292	    }
293	}
