296	static void _g2d_render_thread_cb(void * ptr)
297	{
298	    lv_draw_g2d_unit_t * u = ptr;
299	
300	    lv_thread_sync_init(&u->sync);
301	    u->inited = true;
302	
303	    while(1) {
304	        /*
305	         * Wait for sync if no task received or _draw_task_buf is empty.
306	         * The thread will have to run as much as there are pending tasks.
307	         */
308	        while(u->task_act == NULL) {
309	            if(u->exit_status) {
310	                break;
311	            }
312	            lv_thread_sync_wait(&u->sync);
313	        }
314	
315	        if(u->exit_status) {
316	            LV_LOG_INFO("ready to exit g2d rendering thread");
317	            break;
318	        }
319	
320	        _g2d_execute_drawing(u);
321	
322	        /* Cleanup. */
323	        u->task_act->state = LV_DRAW_TASK_STATE_READY;
324	        u->task_act = NULL;
325	
326	        /* The draw unit is free now. Request a new dispatching as it can get a new task. */
327	        lv_draw_dispatch_request();
328	    }
329	
330	    u->inited = false;
331	    lv_thread_sync_delete(&u->sync);
332	    LV_LOG_INFO("exit g2d rendering thread");
333	
334	}
