317	int g2d_wait_cmd_finish(unsigned int timeout)
318	{
319		int ret;
320	
321		ret = hal_sem_timedwait(g2d_ext_hd.queue_sem, timeout * 10);
322		if (ret < 0) {
323			hal_msleep(10);
324			if (g2d_irq_query()) {
325				syslog(LOG_ERR, "G2D generated irq but not responded\n");
326				g2d_bsp_reset();
327				return 0;
328			}
329	
330	        g2d_bsp_reset();
331	        syslog(LOG_ERR, "G2D irq pending flag timeout\n");
332	        return -1;
333	    }
334		g2d_bsp_reset();
335	    return 0;
336	}
