175	                    return 0;
176	                }
177	
178	                if(t->preference_score > 70) {
179	                    t->preference_score = 70;
180	                    t->preferred_draw_unit_id = DRAW_UNIT_ID_G2D;
181	                }
182	                return 1;
183	            }
184	
185	        case LV_DRAW_TASK_TYPE_LAYER: {
186	                const lv_draw_image_dsc_t * draw_dsc = (lv_draw_image_dsc_t *) t->draw_dsc;
187	                lv_layer_t * layer_to_draw = (lv_layer_t *)draw_dsc->src;
188	                //lv_draw_buf_t * draw_buf = &layer_to_draw->draw_buf;
189	
190	                if(!_g2d_cf_supported(layer_to_draw->color_format))
191	                    return 0;
192	
193	                if(!_g2d_draw_img_supported(draw_dsc, size))
194	                    return 0;
195	
196	                if(t->preference_score > 70) {
197	                    t->preference_score = 70;
198	                    t->preferred_draw_unit_id = DRAW_UNIT_ID_G2D;
199	                }
200	                return 1;
201	            }
202	
203	        case LV_DRAW_TASK_TYPE_IMAGE: {
204	                lv_draw_image_dsc_t * img_dsc = (lv_draw_image_dsc_t *) t->draw_dsc;
205	                if(!_g2d_cf_supported(img_dsc->header.cf))
206	                    return 0;
207	
208	                if(!_g2d_draw_img_supported(img_dsc, size))
