272	/* --- button actions --- */
273	
274	static void scope_act_zoom(int dir)
275	{
276	  int i;
277	  int idx = -1;
278	
279	  for (i = 0; i < (int)ZOOM_TABLE_LEN; i++)
280	    {
281	      if (g_zoom_table[i] == g_ui.zoom)
282	        {
283	          idx = i;
284	          break;
285	        }
286	    }
287	
288	  if (idx < 0)
289	    {
290	      idx = 0;
291	    }
292	
293	  idx += dir;
294	  if (idx < 0 || idx >= (int)ZOOM_TABLE_LEN)
295	    {
296	      return;
297	    }
298	
299	  scope_set_zoom(g_zoom_table[idx]);
300	  scope_apply_view();
301	}
302	
303	static void scope_act_pan(int dir)
304	{
305	  uint32_t span = scope_span();
306	  uint32_t maxpan = SCOPE_POINT_CNT - span;
307	  uint32_t step = (maxpan + 7) / 8;
308	
309	  if (step < 1)
310	    {
311	      step = 1;
312	    }
313	
314	  if (dir > 0)
315	    {
316	      /* pan further back into history */
317	
318	      if (g_ui.pan < maxpan)
319	        {
320	          g_ui.pan = g_ui.pan + step;
321	          if (g_ui.pan > maxpan)
322	            {
323	              g_ui.pan = maxpan;
324	            }
325	
326	          scope_apply_view();
327	        }
328	    }
329	  else
330	    {
331	      /* pan back toward the cursor */
332	
333	      if (g_ui.pan >= step)
334	        {
335	          g_ui.pan -= step;
336	        }
337	      else if (g_ui.pan > 0)
338	        {
339	          g_ui.pan = 0;
340	        }
341	
342	      scope_apply_view();
343	    }
344	}
345	
346	static void scope_act_clear(void)
347	{
348	  uint32_t i;
349	
350	  for (i = 0; i < SCOPE_POINT_CNT; i++)
351	    {
352	      lv_chart_set_value_by_id(g_ui.chart_cur, g_ui.ser_id, i, LV_CHART_POINT_NONE);
353	      lv_chart_set_value_by_id(g_ui.chart_cur, g_ui.ser_iq, i, LV_CHART_POINT_NONE);
354	      lv_chart_set_value_by_id(g_ui.chart_rpm, g_ui.ser_rpm, i, LV_CHART_POINT_NONE);
355	    }
356	}
357	
358	static void scope_act_channel(void)
359	{
360	  g_ui.ch_mode = (g_ui.ch_mode + 1) % 3;
361	
362	  lv_chart_hide_series(g_ui.chart_cur, g_ui.ser_id,
363	                       (g_ui.ch_mode != 0 && g_ui.ch_mode != 1));
364	  lv_chart_hide_series(g_ui.chart_cur, g_ui.ser_iq,
365	                       (g_ui.ch_mode != 0 && g_ui.ch_mode != 2));
366	}
367	
368	static void scope_act_scale(void)
369	{
370	  g_ui.scale_idx = (g_ui.scale_idx + 1) % SCALE_MAIN_LEN;
371	
372	  lv_chart_set_range(g_ui.chart_cur, LV_CHART_AXIS_PRIMARY_Y,
373	                     g_scale_main[g_ui.scale_idx][0],
374	                     g_scale_main[g_ui.scale_idx][1]);
375	}
376	
377	static void scope_btn_cb(lv_event_t *e)
378	{
379	  int act = (int)(intptr_t)lv_event_get_user_data(e);
380	
381	  switch (act)
382	    {
383	      case ACT_PAUSE:
384	        scope_set_state(g_ui.state == SCOPE_STATE_RUN ?
385	                        SCOPE_STATE_PAUSED : SCOPE_STATE_RUN);
386	        break;
387	
388	      case ACT_ZOOM_IN:
389	        scope_act_zoom(1);
390	        break;
391	
392	      case ACT_ZOOM_OUT:
393	        scope_act_zoom(-1);
394	        break;
395	
396	      case ACT_SCALE:
397	        scope_act_scale();
398	        break;
399	
400	      case ACT_CLEAR:
401	        scope_act_clear();
402	        break;
403	
404	      case ACT_LEFT:
405	        scope_act_pan(1);
406	        break;
407	
408	      case ACT_RIGHT:
409	        scope_act_pan(-1);
410	        break;
411	
412	      case ACT_CH:
413	        scope_act_channel();
414	        break;
415	
416	      default:
417	        break;
418	    }
419	}
