462	static lv_obj_t *scope_make_btn(lv_obj_t *parent, int idx, int row,
463	                                const char *txt, int act)
464	{
465	  lv_obj_t *btn = lv_button_create(parent);
466	  lv_obj_t *lab;
467	
468	  lv_obj_set_pos(btn, SCOPE_BTN_X(idx),
469	                 row == 0 ? SCOPE_BTN_Y1 : SCOPE_BTN_Y2);
470	  lv_obj_set_size(btn, SCOPE_BTN_W, SCOPE_BTN_H);
471	  lv_obj_add_event_cb(btn, scope_btn_cb, LV_EVENT_CLICKED,
472	                      (void *)(intptr_t)act);
473	
474	  lv_obj_set_style_bg_color(btn, CLR_BTN_BG, 0);
475	  lv_obj_set_style_bg_color(btn, CLR_BTN_BG_PRS, LV_STATE_PRESSED);
476	  lv_obj_set_style_bg_color(btn, CLR_BTN_BG_DIS, LV_STATE_DISABLED);
477	  lv_obj_set_style_border_color(btn, CLR_BTN_BD, 0);
478	  lv_obj_set_style_border_width(btn, 1, 0);
479	  lv_obj_set_style_radius(btn, 4, 0);
480	  lv_obj_set_style_shadow_width(btn, 0, 0);
481	  lv_obj_set_style_text_color(btn, CLR_TEXT, 0);
482	  lv_obj_set_style_text_color(btn, CLR_BTN_TXT_DIS, LV_STATE_DISABLED);
483	
484	  lab = lv_label_create(btn);
485	  lv_label_set_text(lab, txt);
486	  lv_obj_center(lab);
487	
488	  return btn;
489	}
