          tmp     = (uint32_t)*ptr++;
          regval |= tmp << CAN_TMDTL_TMDT1_SHIFT;

          if (dlc > 2)
            {
              tmp     = (uint32_t)*ptr++;
              regval |= tmp << CAN_TMDTL_TMDT2_SHIFT;

              if (dlc > 3)
                {
                  tmp     = (uint32_t)*ptr++;
                  regval |= tmp << CAN_TMDTL_TMDT3_SHIFT;
                }
