/****************************************************************************
 * chips/r528/r528_can.c
 *
 * Allwinner R528 (sun8iw20 / sun20i-d1 family) CAN0/CAN1 controller driver
 * for NuttX.
 *
 * The R528 CAN controller is the same IP as on the D1/T113 (compatible
 * "allwinner,sun20i-d1-can" in mainline Linux).  The register logic in this
 * driver follows the mainline sun4i_can.c driver; the NuttX CAN framework
 * wiring follows the AT32 CAN driver (nuttx/arch/arm/src/at32/at32_can.c).
 *
 * Hardware facts (verified against DShanPi schematic + T113 manual):
 *   - CAN0 @ 0x02504000, CAN1 @ 0x02504400 (4KB reg space each)
 *   - GIC SPI 21 (CAN0) / SPI 22 (CAN1)  ->  NuttX IRQ 53 / 54 (SPI+32)
 *   - CCU @ 0x02001000 + 0x92c: bit0 = BUS_CAN0 gate, bit1 = BUS_CAN1 gate,
 *     bit16/17 = CAN0/CAN1 reset (deassert = write 1)
 *   - GPIO @ 0x02000000: PB_CFG0 = 0x24; PB2/PB3 = CAN0 TX/RX, PB4/PB5 =
 *     CAN1 TX/RX, each 4-bit mux field, function value 0x8
 *   - Controller clock = APB1 = 24 MHz.  500 kbit/s: brp=2, tseg1=16,
 *     tseg2=7, sjw=1  (24MHz / (2 * (16+7+1)) = 500k)
 *
 * On this D1-family part the acceptance code/mask registers live at
 * 0x28/0x2c (SUN4I_CAN_ACPC/ACPM are at 0x40/0x44 only on older sun4i).
 *
 ****************************************************************************/

/****************************************************************************
 * Included Files
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/types.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <errno.h>
#include <debug.h>

#include <nuttx/irq.h>
#include <nuttx/arch.h>
#include <nuttx/can/can.h>
#include <nuttx/semaphore.h>

#include "chip.h"
#include "r528_irq.h"

#ifdef CONFIG_R528_CAN

/****************************************************************************
 * Pre-processor Definitions
 ****************************************************************************/

/* Controller register offsets (base-relative) */

#define R528_CAN_MSEL_OFFSET   0x0000 /* Mode select (r/w) */
#define R528_CAN_CMD_OFFSET    0x0004 /* Command (r/w) */
#define R528_CAN_STA_OFFSET    0x0008 /* Status (r) */
#define R528_CAN_INT_OFFSET    0x000c /* Interrupt flag (r) */
#define R528_CAN_INTEN_OFFSET  0x0010 /* Interrupt enable (r/w) */
#define R528_CAN_BTIME_OFFSET  0x0014 /* Bus timing (r/w, reset mode only) */
#define R528_CAN_TEWL_OFFSET   0x0018 /* Tx error warning limit (r/w) */
#define R528_CAN_ERRC_OFFSET   0x001c /* Error counter (r) */
#define R528_CAN_RMCNT_OFFSET  0x0020 /* RX message counter (r) */
#define R528_CAN_RBUFSA_OFFSET 0x0024 /* RX buffer start address (r/w) */
#define R528_CAN_ACPC_OFFSET   0x0028 /* Acceptance code 0 (D1 quirk) */
#define R528_CAN_ACPM_OFFSET   0x002c /* Acceptance mask 0 (D1 quirk) */
#define R528_CAN_BUF0_OFFSET   0x0040 /* Tx/Rx message buffer 0..12 */
#define R528_CAN_BUF12_OFFSET  0x0070

/* Mode select register */

#define R528_CAN_MSEL_SLEEP_MODE        (0x01 << 4) /* Write in reset mode */
#define R528_CAN_MSEL_SINGLE_FILTER     (0x01 << 3) /* Write in reset mode */
#define R528_CAN_MSEL_LOOPBACK_MODE     (1 << 2)
#define R528_CAN_MSEL_LISTEN_ONLY_MODE  (1 << 1)
#define R528_CAN_MSEL_RESET_MODE        (1 << 0)

#define R528_CAN_MODE_MAX_RETRIES       1000

/* Command register */

#define R528_CAN_CMD_BUS_OFF_REQ      (1 << 5)
#define R528_CAN_CMD_SELF_RCV_REQ     (1 << 4)
#define R528_CAN_CMD_CLEAR_OR_FLAG    (1 << 3)
#define R528_CAN_CMD_RELEASE_RBUF     (1 << 2)
#define R528_CAN_CMD_ABORT_REQ        (1 << 1)
#define R528_CAN_CMD_TRANS_REQ        (1 << 0)

/* Status register */

#define R528_CAN_STA_BUS_OFF      (1 << 7)
#define R528_CAN_STA_ERR_STA      (1 << 6)
#define R528_CAN_STA_TRANS_BUSY   (1 << 5)
#define R528_CAN_STA_TRANS_OVER   (1 << 3)
#define R528_CAN_STA_TBUF_RDY     (1 << 2) /* Tx buffer ready (empty) */
#define R528_CAN_STA_DATA_ORUN    (1 << 1)
#define R528_CAN_STA_RBUF_RDY     (1 << 0) /* RX buffer has a message */

/* Interrupt flag register (write 1s to clear) */

#define R528_CAN_INT_BUS_ERR      (1 << 7)
#define R528_CAN_INT_ARB_LOST     (1 << 6)
#define R528_CAN_INT_ERR_PASSIVE  (1 << 5)
#define R528_CAN_INT_WAKEUP       (1 << 4)
#define R528_CAN_INT_DATA_OR      (1 << 3)
#define R528_CAN_INT_ERR_WRN      (1 << 2)
#define R528_CAN_INT_TBUF_VLD     (1 << 1) /* Tx complete */
#define R528_CAN_INT_RBUF_VLD     (1 << 0) /* RX buffer valid */

/* Interrupt enable register */

#define R528_CAN_INTEN_BERR        (1 << 7)
#define R528_CAN_INTEN_ARB_LOST    (1 << 6)
#define R528_CAN_INTEN_ERR_PASSIVE (1 << 5)
#define R528_CAN_INTEN_WAKEUP      (1 << 4)
#define R528_CAN_INTEN_OR          (1 << 3)
#define R528_CAN_INTEN_ERR_WRN     (1 << 2)
#define R528_CAN_INTEN_TX          (1 << 1)
#define R528_CAN_INTEN_RX          (1 << 0)

#define R528_CAN_INTEN_ALL         0xff

/* Message buffer flag bits (BUF0) */

#define R528_CAN_MSG_EFF_FLAG      (1 << 7)
#define R528_CAN_MSG_RTR_FLAG      (1 << 6)

/* Bus timing field positions (BTIME) */

#define R528_CAN_BTIME_BRP_SHIFT   0
#define R528_CAN_BTIME_SJW_SHIFT   14
#define R528_CAN_BTIME_TSEG1_SHIFT 16
#define R528_CAN_BTIME_TSEG2_SHIFT 20
#define R528_CAN_BTIME_3SAMP_BIT   (1 << 23)

/* CCU: bus gate + reset for the CAN controllers */

#define R528_CCU_BASE              0x02001000
#define R528_CCU_CAN_OFFSET        0x92c
#define R528_CCU_CAN0_GATE         (1 << 0)
#define R528_CCU_CAN1_GATE         (1 << 1)
#define R528_CCU_CAN0_RST          (1 << 16)
#define R528_CCU_CAN1_RST          (1 << 17)

/* PIO: PB mux for the CAN pins */

#define R528_PIO_BASE              0x02000000
#define R528_PIO_PB_CFG0_OFFSET    0x24
#define R528_PIO_CAN_MUX           0x8 /* PB2-5 function 8 = CAN0/CAN1 */

/* Controller clock and default bit timing (500 kbit/s) */

#define R528_CAN_CLOCK             24000000 /* APB1 */

/* Default bit timing: brp=2, tseg1=16, tseg2=7, sjw=1 */

#define R528_CAN_BRP               2
#define R528_CAN_TSEG1             16
#define R528_CAN_TSEG2             7
#define R528_CAN_SJW               1

#define R528_CAN_MAX_ISR_LOOPS     16

/****************************************************************************
 * Private Types
 ****************************************************************************/

struct r528_can_s
{
  uint8_t  port;                 /* 0 = CAN0, 1 = CAN1 */
  uint32_t base;                 /* Controller register base */
  uint8_t  irq;                  /* NuttX IRQ number */
  bool     started;              /* True when the cell is in normal mode */
};

/****************************************************************************
