/****************************************************************************
 * Private Functions
 ****************************************************************************/

/****************************************************************************
 * Name: r528can_set_reset_mode
 *
 * Description:
 *   Put the controller into reset mode (required for all configuration).
 *
 ****************************************************************************/

static int r528can_set_reset_mode(FAR struct r528_can_s *priv)
{
  int retries = R528_CAN_MODE_MAX_RETRIES;
  uint32_t regval;

  do
    {
      regval = getreg32(priv->base + R528_CAN_MSEL_OFFSET);
      regval |= R528_CAN_MSEL_RESET_MODE;
      putreg32(regval, priv->base + R528_CAN_MSEL_OFFSET);
    }
  while (--retries > 0 &&
         (getreg32(priv->base + R528_CAN_MSEL_OFFSET) &
          R528_CAN_MSEL_RESET_MODE) == 0);

  if ((getreg32(priv->base + R528_CAN_MSEL_OFFSET) &
       R528_CAN_MSEL_RESET_MODE) == 0)
    {
      canerr("ERROR: CAN%u enter reset mode failed\n", priv->port);
      return -ETIMEDOUT;
    }

  return OK;
}

/****************************************************************************
 * Name: r528can_set_normal_mode
 *
 * Description:
 *   Take the controller out of reset mode (start CAN communication).
 *
 ****************************************************************************/

static int r528can_set_normal_mode(FAR struct r528_can_s *priv)
{
  int retries = R528_CAN_MODE_MAX_RETRIES;
  uint32_t regval;

  do
    {
      regval = getreg32(priv->base + R528_CAN_MSEL_OFFSET);
      regval &= ~R528_CAN_MSEL_RESET_MODE;
      putreg32(regval, priv->base + R528_CAN_MSEL_OFFSET);
    }
  while (--retries > 0 &&
         (getreg32(priv->base + R528_CAN_MSEL_OFFSET) &
          R528_CAN_MSEL_RESET_MODE) != 0);

  if ((getreg32(priv->base + R528_CAN_MSEL_OFFSET) &
       R528_CAN_MSEL_RESET_MODE) != 0)
    {
      canerr("ERROR: CAN%u enter normal mode failed\n", priv->port);
      return -ETIMEDOUT;
    }

  return OK;
}

/****************************************************************************
 * Name: r528can_set_bittime
 *
 * Description:
 *   Write the bus timing register.  Must be in reset mode.
 *
 ****************************************************************************/

static void r528can_set_bittime(FAR struct r528_can_s *priv, uint32_t brp,
                                uint32_t tseg1, uint32_t tseg2,
                                uint32_t sjw)
{
  uint32_t regval;

  regval = (brp - 1) & 0x3ff;
  regval |= ((sjw - 1) & 0x3) << R528_CAN_BTIME_SJW_SHIFT;
  regval |= ((tseg1 - 1) & 0xf) << R528_CAN_BTIME_TSEG1_SHIFT;
  regval |= ((tseg2 - 1) & 0x7) << R528_CAN_BTIME_TSEG2_SHIFT;

  putreg32(regval, priv->base + R528_CAN_BTIME_OFFSET);

  caninfo("CAN%u bittime=0x%08lx (%lu kbit/s)\n",
          priv->port, (unsigned long)regval,
          (unsigned long)(R528_CAN_CLOCK / (brp * (tseg1 + tseg2 + 1)) / 1000));
}

/****************************************************************************
 * Name: r528can_cellinit
 *
 * Description:
 *   Initialize the CAN controller cell.  Must be in reset mode when called.
 *
 ****************************************************************************/

static int r528can_cellinit(FAR struct can_dev_s *dev)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  uint32_t regval;
  int ret;

  /* Put the controller into reset mode */

  ret = r528can_set_reset_mode(priv);
  if (ret < 0)
    {
      return ret;
    }

  /* Accept all messages */

  putreg32(0x00000000, priv->base + R528_CAN_ACPC_OFFSET);
  putreg32(0xffffffff, priv->base + R528_CAN_ACPM_OFFSET);

  /* Clear error counters */

  putreg32(0, priv->base + R528_CAN_ERRC_OFFSET);

  /* Enable all interrupts */

  putreg32(R528_CAN_INTEN_ALL, priv->base + R528_CAN_INTEN_OFFSET);

  /* Select the operation mode */

  regval = getreg32(priv->base + R528_CAN_MSEL_OFFSET);

#ifdef CONFIG_R528_CAN_LOOPBACK
  /* Loopback: own TX frames are received back.  Useful for self-test
   * without a second node on the bus.
   */

  regval |= R528_CAN_MSEL_LOOPBACK_MODE;
#else
  regval &= ~R528_CAN_MSEL_LOOPBACK_MODE;
#endif

  putreg32(regval, priv->base + R528_CAN_MSEL_OFFSET);

  /* Set the bit timing (500 kbit/s default) */

  r528can_set_bittime(priv, R528_CAN_BRP, R528_CAN_TSEG1, R528_CAN_TSEG2,
                      R528_CAN_SJW);

  /* Enter normal mode */

  ret = r528can_set_normal_mode(priv);
  if (ret < 0)
    {
      return ret;
    }

  priv->started = true;
  return OK;
}

/****************************************************************************
 * Name: r528can_reset
 *
 * Description:
 *   Reset the CAN device (called early by can_register()).
 *
 ****************************************************************************/

static void r528can_reset(FAR struct can_dev_s *dev)
{
  FAR struct r528_can_s *priv = dev->cd_priv;

  /* Disable interrupts and enter reset mode */

  putreg32(0, priv->base + R528_CAN_INTEN_OFFSET);
  r528can_set_reset_mode(priv);
  priv->started = false;
}

/****************************************************************************
 * Name: r528can_setup
 *
 * Description:
 *   Configure the CAN cell and attach the interrupt (called on first
 *   open of the device).
 *
 ****************************************************************************/

static int r528can_setup(FAR struct can_dev_s *dev)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  int ret;

  caninfo("CAN%u base=%08x irq=%u\n", priv->port, priv->base, priv->irq);

  /* Initialize the controller cell */

  ret = r528can_cellinit(dev);
  if (ret < 0)
    {
      canerr("ERROR: CAN%u cell initialization failed: %d\n",
             priv->port, ret);
      return ret;
    }

  /* Attach the CAN interrupt */

  ret = irq_attach(priv->irq, r528can_interrupt, dev);
  if (ret < 0)
    {
      canerr("ERROR: Failed to attach CAN%u IRQ (%u)\n", priv->port,
             priv->irq);
      return ret;
    }

  up_enable_irq(priv->irq);
  return OK;
}

/****************************************************************************
 * Name: r528can_shutdown
 *
 * Description:
 *   Shut down the CAN device.
 *
 ****************************************************************************/

static void r528can_shutdown(FAR struct can_dev_s *dev)
{
  FAR struct r528_can_s *priv = dev->cd_priv;

  /* Disable interrupts and return the controller to reset mode */

  up_disable_irq(priv->irq);
  putreg32(0, priv->base + R528_CAN_INTEN_OFFSET);
  r528can_set_reset_mode(priv);
  priv->started = false;
}

/****************************************************************************
 * Name: r528can_rxint
 *
 * Description:
 *   Enable/disable RX interrupts.
 *
 ****************************************************************************/

static void r528can_rxint(FAR struct can_dev_s *dev, bool enable)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  uint32_t regval;

  regval = getreg32(priv->base + R528_CAN_INTEN_OFFSET);
  if (enable)
    {
      regval |= R528_CAN_INTEN_RX;
    }
  else
    {
      regval &= ~R528_CAN_INTEN_RX;
    }

  putreg32(regval, priv->base + R528_CAN_INTEN_OFFSET);
}

/****************************************************************************
 * Name: r528can_txint
 *
 * Description:
 *   Enable/disable TX interrupts.
 *
 ****************************************************************************/

static void r528can_txint(FAR struct can_dev_s *dev, bool enable)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  uint32_t regval;

  regval = getreg32(priv->base + R528_CAN_INTEN_OFFSET);
  if (enable)
    {
      regval |= R528_CAN_INTEN_TX;
    }
  else
    {
      regval &= ~R528_CAN_INTEN_TX;
    }

  putreg32(regval, priv->base + R528_CAN_INTEN_OFFSET);
}

/****************************************************************************
 * Name: r528can_ioctl
 *
 * Description:
 *   Handle CAN device ioctls.
 *
 ****************************************************************************/

static int r528can_ioctl(FAR struct can_dev_s *dev, int cmd,
                         unsigned long arg)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  int ret = -ENOTTY;

  caninfo("CAN%u cmd=%04x arg=%lu\n", priv->port, cmd, arg);

  switch (cmd)
    {
      /* Return the current bit timing */

      case CANIOC_GET_BITTIMING:
        {
          FAR struct canioc_bittiming_s *bt =
            (FAR struct canioc_bittiming_s *)arg;
          uint32_t regval;

          DEBUGASSERT(bt != NULL);

          regval = getreg32(priv->base + R528_CAN_BTIME_OFFSET);
          bt->bt_sjw   = ((regval >> R528_CAN_BTIME_SJW_SHIFT) & 0x3) + 1;
          bt->bt_tseg1 = ((regval >> R528_CAN_BTIME_TSEG1_SHIFT) & 0xf) + 1;
          bt->bt_tseg2 = ((regval >> R528_CAN_BTIME_TSEG2_SHIFT) & 0x7) + 1;
          bt->bt_baud  = R528_CAN_CLOCK /
                         (((regval & 0x3ff) + 1) *
                          (bt->bt_tseg1 + bt->bt_tseg2 + 1));
          ret = OK;
        }
        break;

      /* Set new bit timing (brp is derived, 24 MHz clock) */

      case CANIOC_SET_BITTIMING:
        {
          FAR const struct canioc_bittiming_s *bt =
            (FAR const struct canioc_bittiming_s *)arg;
          uint32_t brp;
          uint32_t total;
          uint32_t clkin;
          int ret2;

          DEBUGASSERT(bt != NULL);
          DEBUGASSERT(bt->bt_baud > 0 && bt->bt_baud <= R528_CAN_CLOCK);
          DEBUGASSERT(bt->bt_sjw > 0 && bt->bt_sjw <= 4);
          DEBUGASSERT(bt->bt_tseg1 > 0 && bt->bt_tseg1 <= 16);
          DEBUGASSERT(bt->bt_tseg2 > 0 && bt->bt_tseg2 <= 8);

          total = bt->bt_tseg1 + bt->bt_tseg2 + 1;
          clkin = R528_CAN_CLOCK / bt->bt_baud;
          brp   = clkin / total;
          if (brp < 1 || brp > 64 || (clkin % total) != 0)
            {
              ret = -EINVAL;
              break;
            }

          /* Reconfigure in reset mode */

          ret2 = r528can_set_reset_mode(priv);
          if (ret2 < 0)
            {
              ret = ret2;
              break;
            }

          r528can_set_bittime(priv, brp, bt->bt_tseg1, bt->bt_tseg2,
                              bt->bt_sjw);

          ret2 = r528can_set_normal_mode(priv);
          if (ret2 < 0)
            {
              ret = ret2;
              break;
            }

          ret = OK;
        }
        break;

      default:
        break;
    }

  return ret;
}

/****************************************************************************
 * Name: r528can_remoterequest
 *
 * Description:
 *   Send a remote request frame.
 *
 ****************************************************************************/

static int r528can_remoterequest(FAR struct can_dev_s *dev, uint16_t id)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  uint32_t msg_flag_n;

  caninfo("CAN%u request id=%u\n", priv->port, id);

  /* Standard frame remote request, DLC=0 */

  msg_flag_n = R528_CAN_MSG_RTR_FLAG;

  putreg32((id >> 3) & 0xff, priv->base + R528_CAN_BUF0_OFFSET + 0x4);
  putreg32((id << 5) & 0xe0, priv->base + R528_CAN_BUF0_OFFSET + 0x8);
  putreg32(msg_flag_n, priv->base + R528_CAN_BUF0_OFFSET);

  putreg32(R528_CAN_CMD_TRANS_REQ, priv->base + R528_CAN_CMD_OFFSET);
  return OK;
}

/****************************************************************************
 * Name: r528can_send
 *
 * Description:
 *   Send one message from the upper half.
 *
 ****************************************************************************/

static int r528can_send(FAR struct can_dev_s *dev,
                        FAR struct can_msg_s *msg)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  FAR uint8_t *ptr;
  uint32_t msg_flag_n;
  uint32_t dreg;
  int i;

  caninfo("CAN%u ID: %u DLC: %u\n", priv->port,
          (unsigned int)msg->cm_hdr.ch_id, msg->cm_hdr.ch_dlc);

  if (msg->cm_hdr.ch_dlc > CAN_MAXDATALEN)
    {
      canerr("ERROR: DLC out of range: %u\n", msg->cm_hdr.ch_dlc);
      return -EINVAL;
    }

  msg_flag_n = msg->cm_hdr.ch_dlc;

#ifdef CONFIG_CAN_USE_RTR
  if (msg->cm_hdr.ch_rtr)
    {
      msg_flag_n |= R528_CAN_MSG_RTR_FLAG;
    }
#endif

#ifdef CONFIG_CAN_EXTID
  if (msg->cm_hdr.ch_extid)
    {
      DEBUGASSERT(msg->cm_hdr.ch_id < (1 << 29));
      msg_flag_n |= R528_CAN_MSG_EFF_FLAG;
      dreg = R528_CAN_BUF0_OFFSET + 0x14;  /* BUF5 */
      putreg32((msg->cm_hdr.ch_id >> 21) & 0xff,
               priv->base + R528_CAN_BUF0_OFFSET + 0x4);
      putreg32((msg->cm_hdr.ch_id >> 13) & 0xff,
               priv->base + R528_CAN_BUF0_OFFSET + 0x8);
      putreg32((msg->cm_hdr.ch_id >> 5) & 0xff,
               priv->base + R528_CAN_BUF0_OFFSET + 0xc);
      putreg32((msg->cm_hdr.ch_id << 3) & 0xf8,
               priv->base + R528_CAN_BUF0_OFFSET + 0x10);
    }
  else
#endif
    {
      DEBUGASSERT(msg->cm_hdr.ch_id < (1 << 11));
      dreg = R528_CAN_BUF0_OFFSET + 0xc;   /* BUF3 */
      putreg32((msg->cm_hdr.ch_id >> 3) & 0xff,
               priv->base + R528_CAN_BUF0_OFFSET + 0x4);
      putreg32((msg->cm_hdr.ch_id << 5) & 0xe0,
               priv->base + R528_CAN_BUF0_OFFSET + 0x8);
    }

  /* Copy the data bytes into the message buffer */

  ptr = msg->cm_data;
  for (i = 0; i < msg->cm_hdr.ch_dlc; i++)
    {
      putreg32(ptr[i], priv->base + dreg + i * 4);
    }

  /* Set the message flags and request transmission */

  putreg32(msg_flag_n, priv->base + R528_CAN_BUF0_OFFSET);
  putreg32(R528_CAN_CMD_TRANS_REQ, priv->base + R528_CAN_CMD_OFFSET);

  return OK;
}

/****************************************************************************
 * Name: r528can_txready
 *
 * Description:
 *   Return true if the TX buffer is free.
 *
 ****************************************************************************/

static bool r528can_txready(FAR struct can_dev_s *dev)
{
  FAR struct r528_can_s *priv = dev->cd_priv;

  return (getreg32(priv->base + R528_CAN_STA_OFFSET) &
          R528_CAN_STA_TBUF_RDY) != 0;
}

/****************************************************************************
 * Name: r528can_txempty
 *
 * Description:
 *   Return true if the TX buffer is empty.
 *
 ****************************************************************************/

static bool r528can_txempty(FAR struct can_dev_s *dev)
{
  return r528can_txready(dev);
}

/****************************************************************************
 * Name: r528can_receive
 *
 * Description:
 *   Fetch one message from the RX buffer and pass it to the upper half.
 *   The message buffer is released to the hardware.
 *
 ****************************************************************************/

static int r528can_receive(FAR struct can_dev_s *dev)
{
  FAR struct r528_can_s *priv = dev->cd_priv;
  struct can_hdr_s hdr;
  uint8_t data[CAN_MAXDATALEN];
  uint32_t regval;
  uint32_t dreg;
  int i;

  /* Message flags in BUF0: DLC in bits 0-3 */

  regval     = getreg32(priv->base + R528_CAN_BUF0_OFFSET);
  hdr.ch_dlc = regval & 0x0f;
  hdr.ch_tcf = 0;
#ifdef CONFIG_CAN_ERRORS
  hdr.ch_error = 0;
#endif

#ifdef CONFIG_CAN_EXTID
  if (regval & R528_CAN_MSG_EFF_FLAG)
    {
      dreg = R528_CAN_BUF0_OFFSET + 0x14;
      hdr.ch_extid = true;
      hdr.ch_id    = (getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0x4) << 21) |
                     (getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0x8) << 13) |
                     (getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0xc) << 5) |
                     ((getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0x10) >> 3) &
                      0x1f);
    }
  else
    {
      dreg = R528_CAN_BUF0_OFFSET + 0xc;
      hdr.ch_extid = false;
      hdr.ch_id    = (getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0x4) << 3) |
                     ((getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0x8) >> 5) &
                      0x7);
    }
#else
  if (regval & R528_CAN_MSG_EFF_FLAG)
    {
      /* Extended frames are not supported by this configuration */

      canwarn("WARNING: CAN%u dropped extended frame\n", priv->port);
      putreg32(R528_CAN_CMD_RELEASE_RBUF, priv->base + R528_CAN_CMD_OFFSET);
      return OK;
    }

  dreg = R528_CAN_BUF0_OFFSET + 0xc;
  hdr.ch_id = (getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0x4) << 3) |
              ((getreg32(priv->base + R528_CAN_BUF0_OFFSET + 0x8) >> 5) & 0x7);
#endif

#ifdef CONFIG_CAN_USE_RTR
  hdr.ch_rtr = (regval & R528_CAN_MSG_RTR_FLAG) != 0;
#else
  hdr.ch_rtr = 0;
#endif

  /* Copy the data bytes */

  if (!hdr.ch_rtr)
    {
      for (i = 0; i < hdr.ch_dlc; i++)
        {
          data[i] = getreg32(priv->base + dreg + i * 4);
        }
    }

  /* Release the message buffer back to the hardware */

  putreg32(R528_CAN_CMD_RELEASE_RBUF, priv->base + R528_CAN_CMD_OFFSET);

  /* Pass the message to the upper half driver */

  can_receive(dev, &hdr, data);
  return OK;
}

/****************************************************************************
 * Name: r528can_interrupt
 *
 * Description:
 *   CAN interrupt handler.
 *
 ****************************************************************************/

static int r528can_interrupt(int irq, void *context, FAR void *arg)
{
  FAR struct can_dev_s *dev = (FAR struct can_dev_s *)arg;
  FAR struct r528_can_s *priv;
  uint32_t isrc;
  uint32_t status;
  int n = 0;

  DEBUGASSERT(dev != NULL && dev->cd_priv != NULL);
  priv = dev->cd_priv;

  while (n < R528_CAN_MAX_ISR_LOOPS &&
         (isrc = getreg32(priv->base + R528_CAN_INT_OFFSET)) != 0)
    {
      n++;
      status = getreg32(priv->base + R528_CAN_STA_OFFSET);

      if (isrc & R528_CAN_INT_TBUF_VLD)
        {
          /* Transmission complete */

          can_txdone(dev);
        }

      if ((isrc & R528_CAN_INT_RBUF_VLD) &&
          (isrc & R528_CAN_INT_DATA_OR) == 0)
        {
          /* Drain the RX buffer */

          while (getreg32(priv->base + R528_CAN_STA_OFFSET) &
                 R528_CAN_STA_RBUF_RDY)
            {
              r528can_receive(dev);
            }
        }

      if (isrc & (R528_CAN_INT_DATA_OR | R528_CAN_INT_ERR_WRN |
                  R528_CAN_INT_BUS_ERR | R528_CAN_INT_ERR_PASSIVE |
                  R528_CAN_INT_ARB_LOST))
        {
          /* Error condition: report and recover.
           *
           * A data overrun means the message was lost; re-enter reset mode
           * and restart the controller to resynchronize the FIFO.
           */

          canerr("ERROR: CAN%u error int=0x%08lx status=0x%08lx\n",
                 priv->port, (unsigned long)isrc, (unsigned long)status);

          if (isrc & R528_CAN_INT_DATA_OR)
            {
              r528can_cellinit(dev);
            }
        }

      /* Clear the interrupt flags by writing them back */

      putreg32(isrc, priv->base + R528_CAN_INT_OFFSET);
      getreg32(priv->base + R528_CAN_INT_OFFSET);
    }

  return OK;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

/****************************************************************************
 * Name: r528can_initialize
 *
 * Description:
 *   Enable the CAN clocks/pins and register the CAN devices.  Called from
 *   the board bring-up (r528_bringup).
 *
 ****************************************************************************/

int r528can_initialize(void)
{
  uint32_t regval;
  int ret = OK;

  /* Enable the CAN bus clocks and release the resets (CCU) */

  regval = getreg32(R528_CCU_BASE + R528_CCU_CAN_OFFSET);

#ifdef CONFIG_R528_CAN0
  regval |= R528_CCU_CAN0_GATE | R528_CCU_CAN0_RST;
#endif
#ifdef CONFIG_R528_CAN1
  regval |= R528_CCU_CAN1_GATE | R528_CCU_CAN1_RST;
#endif

  putreg32(regval, R528_CCU_BASE + R528_CCU_CAN_OFFSET);

  /* Configure the PB2-PB5 pin muxes (function 8 = CAN) */

  regval = getreg32(R528_PIO_BASE + R528_PIO_PB_CFG0_OFFSET);

#ifdef CONFIG_R528_CAN0
  regval = (regval & ~(0xf << 8)) | (R528_PIO_CAN_MUX << 8);   /* PB2 TX */
  regval = (regval & ~(0xf << 12)) | (R528_PIO_CAN_MUX << 12); /* PB3 RX */
#endif
#ifdef CONFIG_R528_CAN1
  regval = (regval & ~(0xf << 16)) | (R528_PIO_CAN_MUX << 16); /* PB4 TX */
  regval = (regval & ~(0xf << 20)) | (R528_PIO_CAN_MUX << 20); /* PB5 RX */
#endif

  putreg32(regval, R528_PIO_BASE + R528_PIO_PB_CFG0_OFFSET);

  /* Register the CAN character devices */

#ifdef CONFIG_R528_CAN0
  ret = can_register("/dev/can0", &g_can0dev);
  if (ret < 0)
    {
      canerr("ERROR: Failed to register /dev/can0: %d\n", ret);
    }
#endif

#ifdef CONFIG_R528_CAN1
  if (ret == OK)
    {
      ret = can_register("/dev/can1", &g_can1dev);
      if (ret < 0)
        {
          canerr("ERROR: Failed to register /dev/can1: %d\n", ret);
        }
    }
#endif

  return ret;
}

#endif /* CONFIG_R528_CAN */

