/****************************************************************************
 * apps/examples/cantest/cantest.c
 *
 * CAN0/CAN1 loopback self-test for the R528 CAN driver.
 *
 * Run with the kernel built with CONFIG_R528_CAN_LOOPBACK=y:
 *
 *   nsh> cantest
 *   nsh> cantest 1        (test /dev/can1 instead)
 *
 * Each iteration writes one frame (standard ID, 8 data bytes) and reads it
 * back.  In loopback mode the controller receives its own transmission, so
 * no second node on the bus is required.  Also prints the controller bit
 * timing (expect 500 kbit/s).
 *
 ****************************************************************************/

#include <nuttx/config.h>

#include <sys/types.h>
#include <sys/ioctl.h>
#include <fcntl.h>
#include <stdint.h>
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <errno.h>

#include <nuttx/can/can.h>

#define CANTEST_FRAMES 20
#define CANTEST_ID     0x123

/****************************************************************************
 * Private Functions
 ****************************************************************************/

static int cantest_loop(FAR const char *devname)
{
  struct can_msg_s msg;
  struct canioc_bittiming_s bt;
  ssize_t nbytes;
  int fd;
  int i;
  int j;
  int ret;

  fd = open(devname, O_RDWR);
  if (fd < 0)
    {
      fprintf(stderr, "cantest: open %s failed: %d\n", devname, errno);
      return -1;
    }

  /* Query the bit timing (expect 500000 baud) */

  ret = ioctl(fd, CANIOC_GET_BITTIMING, (unsigned long)&bt);
  if (ret < 0)
    {
      fprintf(stderr, "cantest: GET_BITTIMING failed: %d\n", errno);
    }
  else
    {
      printf("cantest: %s bit timing: sjw=%lu tseg1=%lu tseg2=%lu "
             "baud=%lu\n", devname, (unsigned long)bt.bt_sjw,
             (unsigned long)bt.bt_tseg1, (unsigned long)bt.bt_tseg2,
             (unsigned long)bt.bt_baud);
    }

  /* Loopback: transmit and receive our own frames */

  for (i = 0; i < CANTEST_FRAMES; i++)
    {
      memset(&msg, 0, sizeof(msg));
      msg.cm_hdr.ch_id  = CANTEST_ID;
      msg.cm_hdr.ch_dlc = 8;
      for (j = 0; j < 8; j++)
        {
          msg.cm_data[j] = (uint8_t)(i * 8 + j);
        }

      nbytes = write(fd, &msg, CAN_MSGLEN);
      if (nbytes < 0)
        {
          fprintf(stderr, "cantest: write %d failed: %d\n", i, errno);
          close(fd);
          return -1;
        }

      memset(&msg, 0, sizeof(msg));
      nbytes = read(fd, &msg, CAN_MSGLEN);
      if (nbytes < 0)
        {
          fprintf(stderr, "cantest: read %d failed: %d\n", i, errno);
          close(fd);
          return -1;
        }

      if (msg.cm_hdr.ch_id != CANTEST_ID || msg.cm_hdr.ch_dlc != 8)
        {
          fprintf(stderr, "cantest: frame %d: bad header id=%u dlc=%u\n",
                  i, (unsigned int)msg.cm_hdr.ch_id, msg.cm_hdr.ch_dlc);
          close(fd);
          return -1;
        }

      for (j = 0; j < 8; j++)
        {
          if (msg.cm_data[j] != (uint8_t)(i * 8 + j))
            {
              fprintf(stderr, "cantest: frame %d: data[%d]=0x%02x "
                      "expected 0x%02x\n", i, j, msg.cm_data[j],
                      (uint8_t)(i * 8 + j));
              close(fd);
              return -1;
            }
        }

      printf("cantest: frame %d OK id=0x%03x [%02x %02x %02x %02x "
             "%02x %02x %02x %02x]\n", i, (unsigned int)msg.cm_hdr.ch_id,
             msg.cm_data[0], msg.cm_data[1], msg.cm_data[2], msg.cm_data[3],
             msg.cm_data[4], msg.cm_data[5], msg.cm_data[6], msg.cm_data[7]);
    }

  close(fd);
  return 0;
}

/****************************************************************************
 * Public Functions
 ****************************************************************************/

int main(int argc, FAR char *argv[])
{
  int port = 0;

  if (argc > 1)
    {
      port = atoi(argv[1]);
      if (port != 0 && port != 1)
        {
          fprintf(stderr, "usage: cantest [0|1]\n");
          return 1;
        }
    }

  printf("cantest: %s loopback test start\n", port == 0 ? "/dev/can0" :
         "/dev/can1");

  return cantest_loop(port == 0 ? "/dev/can0" : "/dev/can1") == 0 ? 0 : 1;
}

