70	static inline void poll_teardown(FAR struct pollfd *fds, nfds_t nfds,
71	                                 FAR int *count)
72	{
73	  unsigned int i;
74	
75	  /* Process each descriptor in the list */
76	
77	  *count = 0;
78	  for (i = 0; i < nfds; i++)
79	    {
80	      if (fds[i].fd >= 0)
81	        {
82	          int status = poll_fdsetup(fds[i].fd, &fds[i], false);
83	          if (status < 0)
84	            {
85	              fds[i].revents |= POLLERR;
86	            }
87	        }
88	
89	      /* Check if any events were posted */
90	
91	      if (fds[i].revents != 0)
92	        {
93	          (*count)++;
94	        }
95	
96	      /* Un-initialize the poll structure */
97	
98	      fds[i].arg = NULL;
99	      fds[i].cb  = NULL;
100	    }
101	}
