109	 ****************************************************************************/
110	
111	static inline int poll_setup(FAR struct pollfd *fds, nfds_t nfds,
112	                             FAR sem_t *sem)
113	{
114	  unsigned int i;
115	  int ret = OK;
116	  int count = 0;
117	
118	  /* Process each descriptor in the list */
119	
120	  for (i = 0; i < nfds; i++)
121	    {
122	      /* Setup the poll descriptor
123	       *
124	       * REVISIT: In a multi-threaded environment, one use case might be to
125	       * share a single, array of struct pollfd in poll() calls on different
126	       * threads.  That use case is not supportable here because the non-
127	       * standard internal fields get reset here on each call to poll()
128	       * on each thread.
129	       */
130	
131	      fds[i].arg     = sem;
132	      fds[i].cb      = poll_default_cb;
133	      fds[i].revents = 0;
134	      fds[i].priv    = NULL;
135	
136	      /* Check for invalid descriptors. "If the value of fd is less than 0,
137	       * events shall be ignored, and revents shall be set to 0 in that entry
138	       * on return from poll()."
139	       *
140	       * NOTE:  There is a potential problem here.  If there is only one fd
141	       * and if it is negative, then poll will hang.  From my reading of the
142	       * spec, that appears to be the correct behavior.
143	       */
144	
145	      if (fds[i].fd >= 0)
146	        {
147	          ret = poll_fdsetup(fds[i].fd, &fds[i], true);
148	          if (ret < 0)
149	            {
150	              poll_teardown(fds, i, &count);
151	              fds[i].revents |= POLLERR;
152	              fds[i].arg = NULL;
153	              fds[i].cb = NULL;
154	              return count + 1;
155	            }
156	          else if (fds[i].revents != 0)
157	            {
158	              count++;
159	            }
160	        }
161	    }
162	
163	  if (count > 0)
164	    {
165	      /* If there are already events available in poll_setup,
166	       * we execute teardown and return immediately.
167	       */
168	
169	      poll_teardown(fds, i, &count);
170	    }
171	
172	  return count;
173	}
