176	 * Name: poll_cleanup
177	 *
178	 * Description:
179	 *   Cleanup the poll operation.
180	 *
181	 ****************************************************************************/
182	
183	static void poll_cleanup(FAR void *arg)
184	{
185	  FAR struct pollfd_s *fdsinfo = (FAR struct pollfd_s *)arg;
186	  int count;
187	
188	  poll_teardown(fdsinfo->fds, fdsinfo->nfds, &count);
189	}
