196	 * Name: poll_fdsetup
197	 *
198	 * Description:
199	 *   Configure (or unconfigure) one file/socket descriptor for the poll
200	 *   operation.  If fds and sem are non-null, then the poll is being setup.
201	 *   if fds and sem are NULL, then the poll is being torn down.
202	 *
203	 ****************************************************************************/
204	
205	int poll_fdsetup(int fd, FAR struct pollfd *fds, bool setup)
206	{
