211	
212	  ret = fs_getfilep(fd, &filep);
213	  if (ret < 0)
214	    {
215	      return ret;
216	    }
217	
218	  DEBUGASSERT(filep != NULL);
219	
220	  /* Let file_poll() do the rest */
221	
222	  ret = file_poll(filep, fds, setup);
223	  fs_putfilep(filep);
224	  return ret;
