241	
242	void poll_default_cb(FAR struct pollfd *fds)
243	{
244	  int semcount = 0;
245	  FAR sem_t *pollsem;
246	
247	  if (fds->arg != NULL)
248	    {
249	      pollsem = (FAR sem_t *)fds->arg;
