258	/****************************************************************************
259	 * Name: poll_notify
260	 *
261	 * Description:
262	 *   Notify the poll, this function should be called by drivers to notify
263	 *   the caller the poll is ready.
264	 *
265	 * Input Parameters:
266	 *   afds     - The fds array
267	 *   nfds     - Number of fds array
268	 *   eventset - List of events to check for activity
269	 *
270	 * Returned Value:
271	 *   None
272	 *
273	 ****************************************************************************/
274	
275	void poll_notify(FAR struct pollfd **afds, int nfds, pollevent_t eventset)
276	{
277	  int i;
278	  FAR struct pollfd *fds;
279	
280	  DEBUGASSERT(afds != NULL && nfds >= 1);
281	
282	  for (i = 0; i < nfds && eventset; i++)
283	    {
284	      fds = afds[i];
285	      if (fds != NULL)
286	        {
287	          /* The error event must be set in fds->revents */
288	
289	          fds->revents |= eventset & (fds->events | POLLERR | POLLHUP);
290	          if ((fds->revents & (POLLERR | POLLHUP)) != 0)
291	            {
292	              /* Error or Hung up, clear POLLOUT event */
293	
294	              fds->revents &= ~POLLOUT;
295	            }
296	
297	          if ((fds->revents != 0 || (fds->events & POLLALWAYS) != 0) &&
298	              fds->cb != NULL)
299	            {
300	              finfo("Report events: %08" PRIx32 "\n", fds->revents);
301	              fds->cb(fds);
302	            }
303	        }
304	    }
305	}
