307	/****************************************************************************
308	 * Name: file_poll
309	 *
310	 * Description:
311	 *   Low-level poll operation based on struct file.  This is used both to (1)
312	 *   support detached file, and also (2) by poll_fdsetup() to perform all
313	 *   normal operations on file descriptors.
314	 *
315	 * Input Parameters:
316	 *   file     File structure instance
317	 *   fds   - The structure describing the events to be monitored, OR NULL if
318	 *           this is a request to stop monitoring events.
319	 *   setup - true: Setup up the poll; false: Teardown the poll
320	 *
321	 * Returned Value:
322	 *  0: Success; Negated errno on failure
323	 *
324	 ****************************************************************************/
325	
326	int file_poll(FAR struct file *filep, FAR struct pollfd *fds, bool setup)
327	{
328	  FAR struct inode *inode;
329	  int ret = -ENOSYS;
330	
331	  DEBUGASSERT(filep != NULL);
332	  inode = filep->f_inode;
333	
334	  if (inode != NULL)
335	    {
336	      /* Is a driver registered? Does it support the poll method?
337	       * If not, return -ENOSYS
338	       */
339	
340	      if ((INODE_IS_DRIVER(inode) || INODE_IS_MQUEUE(inode) ||
341	          INODE_IS_SOCKET(inode) || INODE_IS_PIPE(inode)) &&
342	          inode->u.i_ops != NULL && inode->u.i_ops->poll != NULL)
343	        {
344	          /* Yes, it does... Setup the poll */
345	
346	          ret = inode->u.i_ops->poll(filep, fds, setup);
347	          if (ret < 0)
348	            {
349	              ferr("poll failed:%p, setup:%d, ret:%d\n",
350	                   inode->u.i_ops->poll, setup, ret);
351	            }
352	        }
353	#ifndef CONFIG_DISABLE_MOUNTPOINT
354	      else if (INODE_IS_MOUNTPT(inode) && inode->u.i_mops != NULL &&
355	               inode->u.i_mops->poll != NULL)
356	        {
357	          ret = inode->u.i_mops->poll(filep, fds, setup);
358	          if (ret < 0)
359	            {
360	              ferr("poll failed:%p, setup:%d, ret:%d\n",
361	                   inode->u.i_ops->poll, setup, ret);
362	            }
363	        }
364	#endif
365	
366	      /* Regular files (and block devices) are always readable and
367	       * writable. Open Group: "Regular files shall always poll TRUE for
368	       * reading and writing."
369	       */
370	
371	      else if (INODE_IS_MOUNTPT(inode) || INODE_IS_BLOCK(inode) ||
372	               INODE_IS_MTD(inode))
373	        {
374	          if (setup)
375	            {
376	              poll_notify(&fds, 1, POLLIN | POLLOUT);
377	            }
378	
379	          ret = OK;
380	        }
381	    }
382	  else
383	    {
384	      poll_notify(&fds, 1, POLLERR | POLLHUP);
385	      ret = OK;
386	    }
387	
388	  return ret;
389	}
