391	/****************************************************************************
392	 * Name: poll
393	 *
394	 * Description:
395	 *   poll() waits for one of a set of file descriptors to become ready to
396	 *   perform I/O.  If none of the events requested (and no error) has
397	 *   occurred for any of  the  file  descriptors,  then  poll() blocks until
398	 *   one of the events occurs.
399	 *
400	 * Input Parameters:
401	 *   fds  - List of structures describing file descriptors to be monitored
402	 *   nfds - The number of entries in the list
403	 *   timeout - Specifies an upper limit on the time for which poll() will
404	 *     block in milliseconds.  A negative value of timeout means an infinite
405	 *     timeout.
406	 *
407	 * Returned Value:
408	 *   On success, the number of structures that have non-zero revents fields.
409	 *   A value of 0 indicates that the call timed out and no file descriptors
410	 *   were ready.  On error, -1 is returned, and errno is set appropriately:
411	 *
412	 *   EBADF  - An invalid file descriptor was given in one of the sets.
413	 *   EFAULT - The fds address is invalid
414	 *   EINTR  - A signal occurred before any requested event.
415	 *   EINVAL - The nfds value exceeds a system limit.
416	 *   ENOMEM - There was no space to allocate internal data structures.
417	 *   ENOSYS - One or more of the drivers supporting the file descriptor
418	 *     does not support the poll method.
419	 *
420	 ****************************************************************************/
421	
422	int poll(FAR struct pollfd *fds, nfds_t nfds, int timeout)
423	{
424	  FAR struct pollfd *kfds;
425	  sem_t sem;
426	  int count = 0;
427	  int ret = OK;
428	
429	  DEBUGASSERT(nfds == 0 || fds != NULL);
430	
431	  /* poll() is a cancellation point */
432	
433	  enter_cancellation_point();
434	
435	#ifdef CONFIG_BUILD_KERNEL
436	  /* Allocate kernel memory for the fds */
437	
438	  kfds = fs_heap_malloc(nfds * sizeof(struct pollfd));
439	  if (!kfds)
440	    {
441	      /* Out of memory */
442	
443	      ret = -ENOMEM;
444	      goto out_with_cancelpt;
445	    }
446	
447	  /* Copy the user fds to neutral kernel memory */
448	
449	  memcpy(kfds, fds, nfds * sizeof(struct pollfd));
450	#else
451	  /* Can use the user fds directly */
452	
453	  kfds = fds;
454	#endif
455	
456	  /* Set up the poll structure */
457	
458	  nxsem_init(&sem, 0, 0);
459	
460	  /* If there are already events available in poll_setup,
461	   * we return immediately
462	   */
463	
464	  count = poll_setup(kfds, nfds, &sem);
465	  if (count == 0)
466	    {
467	      struct pollfd_s fdsinfo;
468	
469	      /* Push a cancellation point onto the stack.  This will be called if
470	       * the thread is canceled.
471	       */
472	
473	      fdsinfo.fds = kfds;
474	      fdsinfo.nfds = nfds;
475	      tls_cleanup_push(tls_get_info(), poll_cleanup, &fdsinfo);
476	
477	      if (timeout > 0)
478	        {
479	          /* "Implementations may place limitations on the granularity of
480	           * timeout intervals. If the requested timeout interval requires
481	           * a finer granularity than the implementation supports, the
482	           * actual timeout interval will be rounded up to the next
483	           * supported value." -- opengroup.org
484	           *
485	           * Round timeout up to next full tick.
486	           */
487	
488	          /* Either wait for either a poll event(s), for a signal to occur,
489	           * or for the specified timeout to elapse with no event.
490	           *
491	           * NOTE: If a poll event is pending (i.e., the semaphore has
492	           * already been incremented), nxsem_tickwait() will not wait, but
493	           * will return immediately.
494	           */
495	
496	          ret = nxsem_tickwait(&sem, MSEC2TICK((clock_t)timeout));
497	          if (ret < 0)
498	            {
499	              if (ret == -ETIMEDOUT)
500	                {
501	                  /* Return zero (OK) in the event of a timeout */
502	
503	                  ret = OK;
504	                }
505	
506	              /* EINTR is the only other error expected in normal operation */
507	            }
508	        }
509	      else if (timeout < 0)
510	        {
511	          /* Wait for the poll event or signal with no timeout */
512	
513	          ret = nxsem_wait(&sem);
514	        }
515	
516	      /* Teardown the poll operation and get the count of events.  Zero will
517	       * be returned in the case of a timeout.
518	       *
519	       * Preserve ret, if negative, since it holds the result of the wait.
520	       */
521	
522	      poll_teardown(kfds, nfds, &count);
523	
524	      /* Pop the cancellation point */
525	
526	      tls_cleanup_pop(tls_get_info(), 0);
527	    }
528	
529	  nxsem_destroy(&sem);
530	
531	#ifdef CONFIG_BUILD_KERNEL
532	  /* Copy the events back to user */
533	
534	  if (ret == OK)
535	    {
536	      int i;
537	      for (i = 0; i < nfds; i++)
538	        {
539	          fds[i].revents = kfds[i].revents;
540	        }
541	    }
542	
543	  /* Free the temporary buffer */
544	
545	  fs_heap_free(kfds);
546	
547	out_with_cancelpt:
548	#endif
549	
550	  leave_cancellation_point();
551	
552	  if (ret < 0)
553	    {
554	      set_errno(-ret);
555	      return ERROR;
556	    }
557	  else
558	    {
559	      return count;
560	    }
561	}
