978	 * Name: can_poll
979	 ****************************************************************************/
980	
981	static int can_poll(FAR struct file *filep, FAR struct pollfd *fds,
982	                    bool setup)
983	{
984	  FAR struct inode *inode = filep->f_inode;
985	  FAR struct can_dev_s *dev = inode->i_private;
986	  FAR struct can_reader_s *reader = NULL;
987	  pollevent_t eventset = 0;
988	  irqstate_t flags;
989	  int ret;
990	  int i;
991	
992	  /* Some sanity checking */
993	
994	#ifdef CONFIG_DEBUG_FEATURES
995	  if (dev == NULL || fds == NULL)
996	    {
997	      return -ENODEV;
998	    }
999	#endif
1000	
1001	  /* Ensure exclusive access to sender indices - don't want can_receive or
1002	   * can_read changing them in the middle of the comparison
1003	   */
1004	
1005	  flags = enter_critical_section();
1006	
1007	  DEBUGASSERT(filep->f_priv != NULL);
1008	  reader = (FAR struct can_reader_s *)filep->f_priv;
1009	
1010	  /* Get exclusive access to the poll structures */
1011	
1012	  ret = nxmutex_lock(&dev->cd_polllock);
1013	  if (ret < 0)
1014	    {
1015	      /* A signal received while waiting for access to the poll data
1016	       * will abort the operation
1017	       */
1018	
1019	      goto return_with_irqdisabled;
1020	    }
1021	
1022	  /* Are we setting up the poll?  Or tearing it down? */
1023	
1024	  if (setup)
1025	    {
1026	      /* This is a request to set up the poll.  Find an available
1027	       * slot for the poll structure reference.
1028	       */
1029	
1030	      for (i = 0; i < CONFIG_CAN_NPOLLWAITERS; i++)
1031	        {
1032	          /* Find an available slot */
1033	
1034	          if (dev->cd_fds[i] == NULL)
1035	            {
1036	              /* Bind the poll structure and this slot */
1037	
1038	              dev->cd_fds[i] = fds;
1039	              fds->priv       = &dev->cd_fds[i];
1040	              break;
1041	            }
1042	        }
1043	
1044	      if (i >= CONFIG_CAN_NPOLLWAITERS)
1045	        {
1046	          fds->priv = NULL;
1047	          ret       = -EBUSY;
1048	          goto errout;
1049	        }
1050	
1051	      /* Should we immediately notify on any of the requested events?
1052	       * First, check if the sender is full.
1053	       */
1054	
1055	      if (!TX_FULL(&dev->cd_sender))
1056	        {
1057	          eventset |= POLLOUT;
1058	        }
1059	
1060	      /* Check whether there are messages in the RX FIFO. */
1061	
1062	      if (reader->fifo.rx_head != reader->fifo.rx_tail
1063	#ifdef CONFIG_CAN_ERRORS
1064	          || reader->fifo.rx_error != 0
1065	#endif
1066	         )
1067	        {
1068	          /* No need to wait, just notify the application immediately */
1069	
1070	          eventset |= POLLIN;
1071	        }
1072	
1073	      poll_notify(&fds, 1, eventset);
1074	    }
1075	  else if (fds->priv != NULL)
1076	    {
1077	      /* This is a request to tear down the poll */
1078	
1079	      FAR struct pollfd **slot = (FAR struct pollfd **)fds->priv;
1080	
1081	#ifdef CONFIG_DEBUG_FEATURES
1082	      if (slot == NULL)
1083	        {
1084	          ret = -EIO;
1085	          goto errout;
1086	        }
1087	#endif
1088	
1089	      /* Remove all memory of the poll setup */
1090	
1091	      *slot     = NULL;
1092	      fds->priv = NULL;
1093	    }
1094	
1095	errout:
1096	  nxmutex_unlock(&dev->cd_polllock);
1097	return_with_irqdisabled:

