/* Poll-free diagnostic loop: poll() does not appear to return (timeout never
 * fires on this platform), so instead we busy-sleep 100ms per iteration and
 * read the driver ISR counters via CANIOC_GET_STATS.  This tells us whether
 * the CAN interrupt fires at all (isr), whether TX completes (txdone) and
 * whether the loopback frame lands in the RX FIFO (rx). */

#define CANTEST_POLL_STEPS 10
#define CANTEST_POLL_MS    100

