static int cantest_loop(FAR const char *devname)
{
  struct can_msg_s msg;
  struct canioc_bittiming_s bt;
  ssize_t nbytes;
  int fd;
  int i;
  int j;
  int ret;

  fd = open(devname, O_RDWR);
  printf("cantest: open ret=%d errno=%d\n", fd, errno);
  if (fd < 0)
    {
      fprintf(stderr, "cantest: open %s failed: %d\n", devname, errno);
      return -1;
    }

  /* Query the bit timing (expect 500000 baud) */

  ret = ioctl(fd, CANIOC_GET_BITTIMING, (unsigned long)&bt);
  printf("cantest: ioctl ret=%d errno=%d\n", ret, errno);
  if (ret < 0)
    {
      fprintf(stderr, "cantest: GET_BITTIMING failed: %d\n", errno);
    }
  else
    {
      printf("cantest: %s bit timing: sjw=%lu tseg1=%lu tseg2=%lu "
             "baud=%lu\n", devname, (unsigned long)bt.bt_sjw,
             (unsigned long)bt.bt_tseg1, (unsigned long)bt.bt_tseg2,
             (unsigned long)bt.bt_baud);
    }

  /* Loopback: transmit and receive our own frames */

  for (i = 0; i < CANTEST_FRAMES; i++)
    {
      memset(&msg, 0, sizeof(msg));
      msg.cm_hdr.ch_id  = CANTEST_ID;
      msg.cm_hdr.ch_dlc = 8;
      for (j = 0; j < 8; j++)
        {
          msg.cm_data[j] = (uint8_t)(i * 8 + j);
        }

      printf("cantest: frame %d: write...\n", i);

      if (i == 0)
        {
          struct r528_can_stats_s st;

          memset(&st, 0, sizeof(st));
          ioctl(fd, CANIOC_GET_STATS, (unsigned long)&st);
          printf("cantest: stats before: isr=%lu rx=%lu txdone=%lu\n",
                 (unsigned long)st.isr_cnt, (unsigned long)st.rx_cnt,
                 (unsigned long)st.txdone_cnt);
        }
      nbytes = write(fd, &msg, CAN_MSGLEN(msg.cm_hdr.ch_dlc));
      printf("cantest: frame %d: write ret=%zd errno=%d\n", i, nbytes,
             errno);
      if (nbytes < 0)
        {
          fprintf(stderr, "cantest: write %d failed: %d\n", i, errno);
          close(fd);
          return -1;
        }

      memset(&msg, 0, sizeof(msg));
      printf("cantest: frame %d: read...\n", i);
      {
        struct pollfd pfd;

        pfd.fd     = fd;
        pfd.events = POLLIN;
        ret = poll(&pfd, 1, 2000);
