934	  priv = dev->cd_priv;
935	  priv->isr_cnt++;
936	
937	  while (n < R528_CAN_MAX_ISR_LOOPS &&
938	         (isrc = getreg32(priv->base + R528_CAN_INT_OFFSET)) != 0)
939	    {
940	      n++;
941	      status = getreg32(priv->base + R528_CAN_STA_OFFSET);
942	
