{
    uint32_t * src =  &amp;CAN_TRBUF0(can_base);
    for(int i = 0; i &lt; 13; i++)
       buf[i] = (char)src[i];

     CAN_CMD(can_base) |= (1 &lt;&lt; 2);
}

