/****************************************************************************
 * Name: cantest_send
 *
 * Description:
 *   Peer mode (loopback disabled): transmit CANTEST_FRAMES frames on the
 *   given port and confirm each one actually went out (txdone counter
 *   advances).  The peer is expected to ACK; without an ACK the controller
 *   bus-errors and the driver's bus-off recovery kicks in - frames will
 *   then time out with -EBUSY.
 *
 ****************************************************************************/

static int cantest_send(FAR const char *devname)
{
  struct can_msg_s msg;
  struct r528_can_stats_s st;
  ssize_t nbytes;
  int fd;
  int i;
  int j;
  int ret;
  uint32_t prev_txdone = 0;

  fd = open(devname, O_RDWR);
  printf("cantest: send: open ret=%d errno=%d\n", fd, errno);
  if (fd < 0)
    {
      fprintf(stderr, "cantest: open %s failed: %d\n", devname, errno);
      return -1;
    }

  for (i = 0; i < CANTEST_FRAMES; i++)
    {
      memset(&msg, 0, sizeof(msg));
      msg.cm_hdr.ch_id  = CANTEST_ID;
      msg.cm_hdr.ch_dlc = 8;
      for (j = 0; j < 8; j++)
        {
          msg.cm_data[j] = (uint8_t)(i * 8 + j);
        }

      nbytes = write(fd, &msg, CAN_MSGLEN(msg.cm_hdr.ch_dlc));
      if (nbytes < 0)
        {
          fprintf(stderr, "cantest: send: frame %d: write failed: %d\n",
                  i, errno);
          close(fd);
          return -1;
        }

      /* Wait for TX completion (tbuf freed, frame on the bus) */

      ret = 0;
      for (j = 0; j < CANTEST_POLL_STEPS; j++)
        {
          usleep(CANTEST_POLL_MS * 1000);

          memset(&st, 0, sizeof(st));
          ret = ioctl(fd, CANIOC_GET_STATS, (unsigned long)&st);
          if (ret < 0)
            {
              printf("cantest: send: frame %d: GET_STATS failed errno=%d\n",
                     i, errno);
              break;
            }

          if (st.txdone_cnt > prev_txdone)
            {
              prev_txdone = st.txdone_cnt;
              printf("cantest: send: frame %d: TX done at +%dms "
                     "isr=%lu err=%lx\n", i, (j + 1) * CANTEST_POLL_MS,
                     (unsigned long)st.isr_cnt,
                     (unsigned long)st.isr_last_status);
              ret = 1;
              break;
            }
        }

      if (ret != 1)
        {
          fprintf(stderr, "cantest: send: frame %d: no TX done, aborting\n",
                  i);
          close(fd);
          return -1;
        }
    }

  close(fd);
  printf("cantest: send: %d frames transmitted on %s\n", CANTEST_FRAMES,
         devname);
  return 0;
}

/****************************************************************************
 * Name: cantest_recv
 *
 * Description:
 *   Peer mode (loopback disabled): read CANTEST_FRAMES frames from the
 *   given port (blocking) and verify id/dlc/data against the pattern the
 *   sending side generates (frame i carries bytes [i*8 .. i*8+7]).
 *
 ****************************************************************************/

static int cantest_recv(FAR const char *devname)
{
  struct can_msg_s msg;
  ssize_t nbytes;
  int fd;
  int i;
  int j;

  fd = open(devname, O_RDONLY);
  printf("cantest: recv: open ret=%d errno=%d\n", fd, errno);
  if (fd < 0)
    {
      fprintf(stderr, "cantest: open %s failed: %d\n", devname, errno);
      return -1;
    }

  for (i = 0; i < CANTEST_FRAMES; i++)
    {
      memset(&msg, 0, sizeof(msg));
      nbytes = read(fd, &msg, CAN_MSGLEN(8));
      if (nbytes < 0)
        {
          fprintf(stderr, "cantest: recv: frame %d: read failed: %d\n",
                  i, errno);
          close(fd);
          return -1;
        }

      if (msg.cm_hdr.ch_id != CANTEST_ID || msg.cm_hdr.ch_dlc != 8)
        {
          fprintf(stderr, "cantest: recv: frame %d: bad header id=%u "
                  "dlc=%u\n", i, (unsigned int)msg.cm_hdr.ch_id,
                  msg.cm_hdr.ch_dlc);
          close(fd);
          return -1;
        }

      for (j = 0; j < 8; j++)
        {
          if (msg.cm_data[j] != (uint8_t)(i * 8 + j))
            {
              fprintf(stderr, "cantest: recv: frame %d: data[%d]=0x%02x "
                      "expected 0x%02x\n", i, j, msg.cm_data[j],
                      (uint8_t)(i * 8 + j));
              close(fd);
              return -1;
            }
        }

      printf("cantest: recv: frame %d OK id=0x%03x [%02x %02x %02x %02x "
             "%02x %02x %02x %02x]\n", i, (unsigned int)msg.cm_hdr.ch_id,
             msg.cm_data[0], msg.cm_data[1], msg.cm_data[2], msg.cm_data[3],
             msg.cm_data[4], msg.cm_data[5], msg.cm_data[6], msg.cm_data[7]);
    }

  close(fd);
  printf("cantest: recv: %d frames verified on %s\n", CANTEST_FRAMES,
         devname);
  return 0;
}

