/* 16.16 fixed-point per-frame phase steps (50 SPS cadence):
 * step = freq * 256 table units / 50 * 65536 */

#define CANTEST_BCAST_STEP_IDIQ 167772  /* 0.5 Hz  -> 5 cycles per 10 s window */
#define CANTEST_BCAST_STEP_RPM  16777   /* 0.05 Hz -> slow speed beat */
#define CANTEST_BCAST_STEP_VBUS 671089  /* 2.0 Hz  -> bus ripple */

#define CANTEST_BCAST_MS        20      /* protocol v1 cadence */
#define CANTEST_BCAST_ID        0x501   /* protocol v1 telemetry frame ID */

/* One frame's worth of fake FOC telemetry, little-endian per protocol v1 */

static void cantest_bcast_frame(uint32_t *phase_id, uint32_t *phase_rpm,
                                uint32_t *phase_vbus, FAR uint8_t *d)
{
  int32_t v;

  /* id: 0.5 Hz sine, +/-2500 mA; iq: same frequency, 90 deg behind */

  v = (int32_t)g_sine[(*phase_id >> 16) & 0xff] * 2500 / 32767;
  d[0] = (uint8_t)(v & 0xff);
  d[1] = (uint8_t)((v >> 8) & 0xff);

  v = (int32_t)g_sine[((*phase_id >> 16) + 64) & 0xff] * 2200 / 32767;
  d[2] = (uint8_t)(v & 0xff);
  d[3] = (uint8_t)((v >> 8) & 0xff);

  /* rpm: slow beat around 1600 (UI range 0..3000) */

  v = 1600 + (int32_t)g_sine[(*phase_rpm >> 16) & 0xff] * 500 / 32767;
  d[4] = (uint8_t)(v & 0xff);
  d[5] = (uint8_t)((v >> 8) & 0xff);

  /* vbus: 24.0 V + 2 Hz ripple of +-0.4 V */

  v = 24000 + (int32_t)g_sine[(*phase_vbus >> 16) & 0xff] * 400 / 32767;
  d[6] = (uint8_t)(v & 0xff);
  d[7] = (uint8_t)((v >> 8) & 0xff);

  *phase_id  += CANTEST_BCAST_STEP_IDIQ;
  *phase_rpm += CANTEST_BCAST_STEP_RPM;
  *phase_vbus += CANTEST_BCAST_STEP_VBUS;
}

/****************************************************************************
 * Name: cantest_bcast
 *
 * Description:
 *   Fake drive-board mode: broadcast FOCPILOT CAN protocol v1 telemetry
 *   (ID 0x501, 8 data bytes little-endian, 20 ms cadence) on the given
 *   port.  Lets `focscope can` (which listens on /dev/can0) be exercised
 *   against a live 50 Hz stream - protocol decode, waveform rendering and
 *   the 500 ms stale-link detection - without the real drive board.
 *   Runs forever; stop with nsh `kill <pid>` or reboot.
 *
 ****************************************************************************/

static int cantest_bcast(FAR const char *devname)
{
  struct can_msg_s msg;
  uint32_t phase_id = 0;
  uint32_t phase_rpm = 0;
  uint32_t phase_vbus = 0;
  uint32_t nframes = 0;
  ssize_t nbytes;
  int fd;
  int i;

  fd = open(devname, O_WRONLY);
  printf("cantest: bcast: open ret=%d errno=%d\n", fd, errno);
  if (fd < 0)
    {
      fprintf(stderr, "cantest: open %s failed: %d\n", devname, errno);
      return -1;
    }

  printf("cantest: bcast: 0x%03x @50Hz on %s (fake drive board)\n",
         CANTEST_BCAST_ID, devname);

  for (; ; )
    {
      memset(&msg, 0, sizeof(msg));
      msg.cm_hdr.ch_id  = CANTEST_BCAST_ID;
      msg.cm_hdr.ch_dlc = 8;
      cantest_bcast_frame(&phase_id, &phase_rpm, &phase_vbus, msg.cm_data);

      nbytes = write(fd, &msg, CAN_MSGLEN(msg.cm_hdr.ch_dlc));
      if (nbytes < 0)
        {
          fprintf(stderr, "cantest: bcast: write failed: %d\n", errno);
          close(fd);
          return -1;
        }

      nframes++;
      if ((nframes % 50) == 0)
        {
          printf("cantest: bcast: t=%lus frames=%lu\n",
                 (unsigned long)(nframes / 50),
                 (unsigned long)nframes);
        }

      for (i = 0; i < CANTEST_BCAST_MS * 1000; i += 1000)
        {
          usleep(1000);
        }
    }
}

