482	      case ACT_PAUSE:
483	        scope_set_state(g_ui.state == SCOPE_STATE_RUN ?
484	                        SCOPE_STATE_PAUSED : SCOPE_STATE_RUN);
485	        break;
486	
487	      case ACT_ZOOM_IN:
