489	        break;
490	
491	      case ACT_ZOOM_OUT:
492	        scope_act_zoom(-1);
493	        break;
494	
495	      case ACT_SCALE:
496	        scope_act_scale();
497	        break;
498	
499	      case ACT_CLEAR:
500	        scope_act_clear();
501	        break;
502	
503	      case ACT_LEFT:
504	        scope_act_pan(1);
505	        break;
506	
507	      case ACT_RIGHT:
508	        scope_act_pan(-1);
509	        break;
510	
511	      case ACT_CH:
512	        scope_act_channel();
513	        break;
