        else {
            tick_value = i / t->minor_cnt;
        }

        line_dsc.base.id2 = i;
        if(major && t->label_en) {
            char buf[LV_CHART_LABEL_MAX_TEXT_LENGTH];
            lv_snprintf(buf, sizeof(buf), "%" LV_PRId32, tick_value);
            label_dsc.text = buf;
            label_dsc.text_local = true;
            /*reserve appropriate area*/
            lv_point_t size;
            lv_text_get_size(&size, buf, label_dsc.font, label_dsc.letter_space, label_dsc.line_space, LV_COORD_MAX,
                             LV_TEXT_FLAG_NONE);

            /*set the area at some distance of the major tick len under of the tick*/
            lv_area_t a;
            a.x1 = (int32_t)(line_dsc.p2.x - size.x / 2);
            a.x2 = (int32_t)(line_dsc.p2.x + size.x / 2);
            if(sec_axis) {
                a.y2 = (int32_t)(line_dsc.p2.y - label_gap);
                a.y1 = a.y2 - size.y;
            }
            else {
                a.y1 = (int32_t)(line_dsc.p2.y + label_gap);
                a.y2 = a.y1 + size.y;
            }

            if(a.x2 >= obj->coords.x1 &&
               a.x1 <= obj->coords.x2) {
                label_dsc.base.id2 = i;
                lv_draw_label(layer, &label_dsc, &a);
            }
        }

