1	/****************************************************************************
2	 * apps/examples/focscope/scope_data_can.c
3	 *
4	 * FOCPilot CAN telemetry data source (FOCPILOT CAN PROTOCOL v1).
5	 *
6	 * A reader thread opens the CAN device and consumes every broadcast frame:
7	 *
8	 *   ID 0x501, standard frame, 8 data bytes, little-endian, ~50 Hz
9	 *     [0:1] id   int16  mA   (d-axis current,  +/-32767 mA)
10	 *     [2:3] iq   int16  mA   (q-axis current,  +/-32767 mA)
11	 *     [4:5] rpm  int16  rpm  (rotor speed,     +/-32767 rpm)
12	 *     [6:7] vbus uint16 mV   (bus voltage,     0..65535 mV)
13	 *
14	 * The UI polls get_sample() from the LVGL timer callback (single thread).
15	 * The reader thread only touches CAN + a mutex-guarded latest-sample slot,
16	 * never LVGL, so the single-threaded UI constraint is preserved.
17	 *
18	 * If no frame arrives within SCOPE_CAN_STALE_MS the source reports an
19	 * error and the UI stops advancing the traces (link lost); once frames
20	 * resume the traces continue automatically.
21	 *
22	 ****************************************************************************/
23	
24	#include <nuttx/config.h>
25	
26	#include <sys/types.h>
27	#include <fcntl.h>
28	#include <pthread.h>
29	#include <stdint.h>
30	#include <stdbool.h>
31	#include <stdio.h>
32	#include <string.h>
33	#include <unistd.h>
34	#include <errno.h>
35	#include <time.h>
36	
37	#include <nuttx/can/can.h>
38	
39	#include "scope_data.h"
40	
41	/****************************************************************************
42	 * Pre-processor Definitions
43	 ****************************************************************************/
44	
45	/* FOCPilot CAN telemetry protocol v1 */
46	
47	#define SCOPE_CAN_ID           0x501 /* Broadcast telemetry frame ID */
48	#define SCOPE_CAN_MAX_DLC      8
49	
50	/* Reader thread parameters */
51	
52	#define SCOPE_CAN_STALE_MS     500   /* Link considered lost after this */
53	#define SCOPE_CAN_INIT_TIMEOUT_MS 2000 /* No frame yet since open */
54	
55	/* Main chart is mA: UI multiplies A by 1000, so mA maps 1:1 */
56	
57	/****************************************************************************
58	 * Private Types
59	 ****************************************************************************/
60	
61	struct scope_can_s
62	{
63	  scope_ds_t   ds;
64	  pthread_t    tid;
65	  int          fd;
66	  bool         running;
67	
68	  pthread_mutex_t lock;
69	  struct timespec t_open;   /* Reader start time */
70	  struct timespec t_last;   /* Last frame arrival */
71	  bool           fresh;     /* A frame arrived since the last get_sample() */
72	  scope_sample_t latest;
73	};
74	
75	/****************************************************************************
76	 * Private Data
77	 ****************************************************************************/
78	
79	/* focscope is single-instance, so one static source is fine */
80	
81	static struct scope_can_s g_can;
82	
83	/****************************************************************************
84	 * Private Functions
85	 ****************************************************************************/
86	
87	/****************************************************************************
88	 * Name: scope_can_reader
89	 *
90	 * Description:
91	 *   Blocking CAN reader thread.  Consumes every frame, keeps the latest
92	 *   telemetry sample.
93	 *
94	 ****************************************************************************/
95	
96	static FAR void *scope_can_reader(FAR void *arg)
97	{
98	  struct scope_can_s *priv = (FAR struct scope_can_s *)arg;
99	  struct can_msg_s msg;
100	  scope_sample_t s;
101	  uint32_t raw;
102	  ssize_t nbytes;
103	
104	  while (priv->running)
105	    {
106	      memset(&msg, 0, sizeof(msg));
107	      nbytes = read(priv->fd, &msg, CAN_MSGLEN(SCOPE_CAN_MAX_DLC));
108	      if (nbytes < 0)
109	        {
110	          if (errno == EINTR)
111	            {
112	              continue;
113	            }
114	
115	          /* Device went away (or fatal error): stop the thread */
116	
117	          break;
118	        }
119	
120	      /* Only accept our telemetry frame */
121	
122	      if (msg.cm_hdr.ch_id != SCOPE_CAN_ID || msg.cm_hdr.ch_dlc < 8)
123	        {
124	          continue;
125	        }
126	
127	      /* Little-endian decode (match the drive-board implementation) */
128	
129	      raw     = (uint32_t)msg.cm_data[0] | ((uint32_t)msg.cm_data[1] << 8);
130	      s.id    = (float)(int16_t)raw / 1000.0f;
131	
132	      raw     = (uint32_t)msg.cm_data[2] | ((uint32_t)msg.cm_data[3] << 8);
133	      s.iq    = (float)(int16_t)raw / 1000.0f;
134	
135	      raw     = (uint32_t)msg.cm_data[4] | ((uint32_t)msg.cm_data[5] << 8);
136	      s.speed = (float)(int16_t)raw;
137	
138	      raw     = (uint32_t)msg.cm_data[6] | ((uint32_t)msg.cm_data[7] << 8);
139	      s.vbus  = (float)raw / 1000.0f;
140	
141	      pthread_mutex_lock(&priv->lock);
142	      priv->latest = s;
143	      priv->fresh  = true;
144	      clock_gettime(CLOCK_MONOTONIC, &priv->t_last);
145	      pthread_mutex_unlock(&priv->lock);
146	    }
147	
148	  return NULL;
149	}
150	
151	/****************************************************************************
152	 * Name: scope_can_elapsed_ms
153	 *
154	 * Description:
155	 *   Milliseconds elapsed between a and b (a >= b).
156	 *
157	 ****************************************************************************/
158	
159	static int64_t scope_can_elapsed_ms(FAR const struct timespec *a,
160	                                    FAR const struct timespec *b)
161	{
162	  return (int64_t)(a->tv_sec - b->tv_sec) * 1000 +
163	         (a->tv_nsec - b->tv_nsec) / 1000000;
164	}
165	
166	/****************************************************************************
167	 * Public Functions
168	 ****************************************************************************/
169	
170	/****************************************************************************
171	 * Name: scope_ds_can_init
172	 *
173	 ****************************************************************************/
174	
175	static int scope_ds_can_init(FAR scope_ds_t *ds)
176	{
177	  struct scope_can_s *priv = &g_can;
178	  int ret;
179	
180	  priv->fd = open("/dev/can0", O_RDONLY);
181	  if (priv->fd < 0)
182	    {
183	      fprintf(stderr, "scope_can: open /dev/can0 failed: %d\n", errno);
184	      return -1;
185	    }
186	
187	  pthread_mutex_init(&priv->lock, NULL);
188	  clock_gettime(CLOCK_MONOTONIC, &priv->t_open);
189	  priv->t_last = priv->t_open;
190	  priv->fresh  = false;
191	  memset(&priv->latest, 0, sizeof(priv->latest));
192	  priv->running = true;
193	
194	  ret = pthread_create(&priv->tid, NULL, scope_can_reader, priv);
195	  if (ret != 0)
196	    {
197	      fprintf(stderr, "scope_can: thread create failed: %d\n", ret);
198	      close(priv->fd);
199	      priv->fd = -1;
200	      priv->running = false;
201	      return -1;
202	    }
203	
204	  return 0;
205	}
206	
207	/****************************************************************************
208	 * Name: scope_ds_can_deinit
209	 *
210	 ****************************************************************************/
211	
212	static void scope_ds_can_deinit(FAR scope_ds_t *ds)
213	{
214	  struct scope_can_s *priv = &g_can;
215	
216	  priv->running = false;
217	  pthread_cancel(priv->tid);
218	  pthread_join(priv->tid, NULL);
219	  if (priv->fd >= 0)
220	    {
221	      close(priv->fd);
222	      priv->fd = -1;
223	    }
224	
225	  pthread_mutex_destroy(&priv->lock);
226	}
227	
228	/****************************************************************************
229	 * Name: scope_ds_can_get_sample
230	 *
231	 * Description:
232	 *   Return the latest telemetry sample.  Never blocks (the reader thread
233	 *   does the I/O).  Reports an error when no frame has arrived for
234	 *   SCOPE_CAN_STALE_MS (link lost) so the UI stops the traces; normal
235	 *   operation resumes automatically.
236	 *
237	 ****************************************************************************/
238	
239	static int scope_ds_can_get_sample(FAR scope_ds_t *ds, FAR scope_sample_t *s)
240	{
241	  struct scope_can_s *priv = &g_can;
242	  struct timespec now;
243	  int64_t since_last;
244	  int64_t since_open;
245	
246	  clock_gettime(CLOCK_MONOTONIC, &now);
247	
248	  pthread_mutex_lock(&priv->lock);
249	  since_last = scope_can_elapsed_ms(&now, &priv->t_last);
250	  since_open = scope_can_elapsed_ms(&now, &priv->t_open);
251	
252	  if ((!priv->fresh && since_last > SCOPE_CAN_STALE_MS) ||
253	      (!priv->fresh && since_open > SCOPE_CAN_INIT_TIMEOUT_MS))
254	    {
255	      pthread_mutex_unlock(&priv->lock);
256	      return -1;
257	    }
258	
259	  *s = priv->latest;
260	  priv->fresh = false;
261	  pthread_mutex_unlock(&priv->lock);
262	
263	  return 0;
264	}
265	
266	/****************************************************************************
267	 * Name: scope_ds_can_get
268	 *
269	 * Description:
270	 *   Factory: CAN-backed data source.  The device path is compile-time
271	 *   fixed to /dev/can0 for now.
272	 *
273	 ****************************************************************************/
274	
275	scope_ds_t scope_ds_can_get(void)
276	{
277	  memset(&g_can, 0, sizeof(g_can));
278	  g_can.fd = -1;
279	
280	  g_can.ds.name       = "CAN0 0x501";
281	  g_can.ds.init       = scope_ds_can_init;
282	  g_can.ds.deinit     = scope_ds_can_deinit;
283	  g_can.ds.get_sample = scope_ds_can_get_sample;
284	
285	  return g_can.ds;
286	}
