/* ---------------------------------------------------------------
 * STM32G4 驱动板参考实现(MCSDK 工程,STM32 HAL,经典 CAN 模式)
 * CubeMX 里启用 FDCAN1,模式选 FDCAN_MODE_NORMAL(CAN Classic),
 * 500 kbit/s,标准帧,用 CubeMX 自动算时序即可。
 * ---------------------------------------------------------------*/

#include <string.h>
#include "main.h"

extern FDCAN_HandleTypeDef hfdcan1;

/* 遥测帧发送(10 ms 周期调用;FDCAN FIFO 满则丢帧,不阻塞) */
void foc_telemetry_send(int16_t id_mA, int16_t iq_mA,
                        int16_t speed_rpm, uint16_t vbus_mV)
{
    FDCAN_TxHeaderTypeDef hdr;
    uint8_t d[8];
    union { int16_t s; uint8_t b[2]; } u16;   /* 小端拆包 */
    union { uint16_t u; uint8_t b[2]; } U16;

    u16.s = id_mA;   d[0] = u16.b[0]; d[1] = u16.b[1];
    u16.s = iq_mA;   d[2] = u16.b[0]; d[3] = u16.b[1];
    u16.s = speed_rpm; d[4] = u16.b[0]; d[5] = u16.b[1];
    U16.u = vbus_mV; d[6] = U16.b[0]; d[7] = U16.b[1];

    hdr.Identifier = 0x501;
    hdr.IdType     = FDCAN_STANDARD_ID;
    hdr.TxFrameType = FDCAN_DATA_FRAME;
    hdr.DataLength = FDCAN_DLC_BYTES_8;
    hdr.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
    hdr.BitRateSwitch = FDCAN_BRS_OFF;
    hdr.FDFormat = FDCAN_CLASSIC_CAN;
    hdr.TxEventFifoControl = FDCAN_NO_TX_EVENTS;
    hdr.MessageMarker = 0;

    /* 丢帧即返回:发送失败不阻塞控制环路 */
    (void)HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &hdr, d);
}
```

