 * 0x501 @ 500k classic CAN, 8B little-endian:
 *   [0:1] id mA i16 | [2:3] iq mA i16 | [4:5] rpm i16 | [6:7] vbus mV u16
 * Protocol doc: FOCPILOT_CAN_PROTOCOL.md
 */

#include <string.h>
#include "main.h"
#include "mc_api.h"
#include "mc_stm_types.h"
#include "mc_config_common.h"
#include "bus_voltage_sensor.h"

extern FDCAN_HandleTypeDef hfdcan1;

/* ISR_FREQUENCY_HZ = PWM 16 kHz / REGULATION_EXECUTION_RATE 1 = 16 kHz.
 * 10 ms = 160 ticks. */
#define FOC_TEL_TICKS_PER_FRAME   (ISR_FREQUENCY_HZ / 100)

static uint16_t s_tel_cnt;

static int16_t foc_tel_clamp_i16(float v)
{
  float mA = v * 1000.0f;
  if (mA >  32767.0f) return  32767;
  if (mA < -32768.0f) return -32768;
  return (int16_t)mA;
}

static void foc_telemetry_send(int16_t id_mA, int16_t iq_mA,
                               int16_t speed_rpm, uint16_t vbus_mV)
{
  FDCAN_TxHeaderTypeDef hdr;
  uint8_t d[8];
  union { int16_t  s; uint8_t b[2]; } s16;
  union { uint16_t u; uint8_t b[2]; } u16;

  s16.s = id_mA;     d[0] = s16.b[0]; d[1] = s16.b[1];
  s16.s = iq_mA;     d[2] = s16.b[0]; d[3] = s16.b[1];
  s16.s = speed_rpm; d[4] = s16.b[0]; d[5] = s16.b[1];
  u16.u = vbus_mV;   d[6] = u16.b[0]; d[7] = u16.b[1];

  hdr.Identifier = 0x501;
  hdr.IdType = FDCAN_STANDARD_ID;
  hdr.TxFrameType = FDCAN_DATA_FRAME;
  hdr.DataLength = FDCAN_DLC_BYTES_8;
  hdr.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
  hdr.BitRateSwitch = FDCAN_BRS_OFF;
  hdr.FDFormat = FDCAN_CLASSIC_CAN;
  hdr.TxEventFifoControl = FDCAN_NO_TX_EVENTS;
  hdr.MessageMarker = 0;

  (void)HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &hdr, d);
}

/* Called from TSK_HighFrequencyTask (16 kHz). 0-return... */
void foc_telemetry_tick(void)
{
  qd_f_t iqd;
  uint16_t vbus_V;

  if (++s_tel_cnt < FOC_TEL_TICKS_PER_FRAME)
    {
      return;
    }
  s_tel_cnt = 0;

  iqd = MC_GetIqdMotor1_F();   /* A (actual id/iq) */
  vbus_V = VBS_GetAvBusVoltage_V(&(BusVoltageSensor_M1._Super));  /* V */

  foc_telemetry_send(foc_tel_clamp_i16(iqd.d),
                     foc_tel_clamp_i16(iqd.q),
                     SPEED_UNIT_2_RPM(MC_GetMecSpeedAverageMotor1()),
                     (uint16_t)(vbus_V * 1000.0f));
}
