/**
  ******************************************************************************
  * @file    foc_telemetry.c
  * @brief   FOCPilot CAN telemetry v1 for STM32G4 + MCSDK 6.x.
  *
  * Frame (classic CAN, 500 kbit/s, standard ID 0x501, 8 bytes little-endian):
  *   [0:1] id   int16  mA   (d-axis current)
  *   [2:3] iq   int16  mA   (q-axis current)
  *   [4:5] rpm  int16  rpm  (mechanical speed)
  *   [6:7] vbus uint16 mV   (bus voltage)
  *
  * 10 ms broadcast, sent even when the motor is stopped (values 0).
  * The receiver declares link-lost after 500 ms without frames.
  * Protocol: FOCPILOT_CAN_PROTOCOL.md
  ******************************************************************************
  */

#include <string.h>

#include "main.h"
#include "drive_parameters.h"
#include "mc_api.h"
#include "mc_stm_types.h"
#include "mc_config_common.h"
#include "bus_voltage_sensor.h"
#include "foc_telemetry.h"

/* FDCAN1 handle defined in main.c */
extern FDCAN_HandleTypeDef hfdcan1;

/* High-frequency task rate = PWM_FREQUENCY / REGULATION_EXECUTION_RATE.
 * 16 kHz -> 160 ticks per 10 ms. */
#define FOC_TEL_TICKS_PER_FRAME   (ISR_FREQUENCY_HZ / 100)

static uint16_t s_tel_cnt;

/* float A -> int16 mA, clamped to protocol range */
static int16_t foc_tel_clamp_i16(float v)
{
  float mA = v * 1000.0f;

  if (mA > 32767.0f)
    {
      return 32767;
    }
  if (mA < -32768.0f)
    {
      return -32768;
    }
  return (int16_t)mA;
}

/* Send one 0x501 frame. FIFO full / bus busy -> frame dropped, never blocks. */
static void foc_telemetry_send(int16_t id_mA, int16_t iq_mA,
                               int16_t speed_rpm, uint16_t vbus_mV)
{
  FDCAN_TxHeaderTypeDef hdr;
  uint8_t d[8];
  union { int16_t  s; uint8_t b[2]; } s16;   /* little-endian packing */
  union { uint16_t u; uint8_t b[2]; } u16;

  s16.s = id_mA;     d[0] = s16.b[0]; d[1] = s16.b[1];
  s16.s = iq_mA;     d[2] = s16.b[0]; d[3] = s16.b[1];
  s16.s = speed_rpm; d[4] = s16.b[0]; d[5] = s16.b[1];
  u16.u = vbus_mV;   d[6] = u16.b[0]; d[7] = u16.b[1];

  hdr.Identifier          = 0x501;
  hdr.IdType              = FDCAN_STANDARD_ID;
  hdr.TxFrameType         = FDCAN_DATA_FRAME;
  hdr.DataLength          = FDCAN_DLC_BYTES_8;
  hdr.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
  hdr.BitRateSwitch       = FDCAN_BRS_OFF;
  hdr.FDFormat            = FDCAN_CLASSIC_CAN;
  hdr.TxEventFifoControl  = FDCAN_NO_TX_EVENTS;
  hdr.MessageMarker       = 0;

  (void)HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &hdr, d);
}

/* Call from TSK_HighFrequencyTask. Sends one frame every 10 ms. */
void foc_telemetry_tick(void)
{
  qd_f_t   iqd;     /* actual id/iq, A (qd order: q first, d second) */
  uint16_t vbus_V;  /* average bus voltage, V */

  if (++s_tel_cnt < FOC_TEL_TICKS_PER_FRAME)
    {
      return;
    }
  s_tel_cnt = 0;

  iqd    = MC_GetIqdMotor1_F();
  vbus_V = VBS_GetAvBusVoltage_V(&(BusVoltageSensor_M1._Super));

  foc_telemetry_send(foc_tel_clamp_i16(iqd.d),      /* id, mA  */
                     foc_tel_clamp_i16(iqd.q),      /* iq, mA  */
                     SPEED_UNIT_2_RPM(MC_GetMecSpeedAverageMotor1()),
                     (uint16_t)((float)vbus_V * 1000.0f));  /* vbus, mV */
}

