340	/* Re-text every label from the active language table. Cheap (8 tiny
341	 * labels), so it is called on every state change as well: the PAUSE
342	 * button label depends on state (暂停/PAUSE while running, 运行/RUN
343	 * while paused). */
344	
345	static void scope_apply_lang(void)
346	{
347	  const struct scope_lang_s *l = &g_lang[g_ui.lang];
348	  int i;
349	
350	  lv_label_set_text(g_ui.lb_title, l->title);
351	  lv_label_set_text(g_ui.lb_lang, l->lang_name);
352	  lv_label_set_text(g_ui.lb_state,
353	                    g_ui.state == SCOPE_STATE_RUN ?
354	                    l->state_run : l->state_paused);
355	
356	  for (i = 0; i < 8; i++)
357	    {
358	      lv_label_set_text(g_ui.lab_btn[i], l->btn[i]);
359	    }
