361	
362	static void scope_set_state(scope_state_t state)
363	{
364	  g_ui.state = state;
365	
366	  if (state == SCOPE_STATE_RUN)
367	    {
368	      /* Resume following the live cursor.  Keep the current zoom (the
369	       * user may have set it while running); only clear the pan - the
370	       * SHIFT window re-anchors itself at the newest samples.
371	       */
372	
373	      g_ui.pan = 0;
374	      scope_refresh_view_label();
375	      lv_obj_set_style_text_color(g_ui.lb_state, CLR_RUN, 0);
376	    }
377	  else
378	    {
379	      /* Freeze the write cursor as the window anchor */
380	
381	      g_ui.cursor = lv_chart_get_x_start_point(g_ui.chart_cur, g_ui.ser_id);
382	      g_ui.pan = 0;
383	      scope_apply_view();
384	      scope_refresh_view_label();
385	      lv_obj_set_style_text_color(g_ui.lb_state, CLR_PAUSED, 0);
386	    }
387	
388	  scope_apply_lang();
389	  scope_set_view_btns_enabled(state == SCOPE_STATE_PAUSED);
390	}
