392	/* --- button actions --- */
393	
394	static void scope_act_zoom(int dir)
395	{
396	  int i;
397	  int idx = -1;
398	
399	  for (i = 0; i < (int)ZOOM_TABLE_LEN; i++)
400	    {
401	      if (g_zoom_table[i] == g_ui.zoom)
402	        {
403	          idx = i;
404	          break;
405	        }
406	    }
407	
408	  if (idx < 0)
409	    {
410	      idx = 0;
411	    }
412	
413	  idx += dir;
414	  if (idx < 0 || idx >= (int)ZOOM_TABLE_LEN)
415	    {
416	      return;
417	    }
418	
419	  scope_set_zoom(g_zoom_table[idx]);
420	
421	  /* In RUN the SHIFT window follows the live cursor by itself; only the
422	   * paused view needs re-anchoring at the frozen cursor.
423	   */
424	
425	  if (g_ui.state == SCOPE_STATE_PAUSED)
426	    {
427	      scope_apply_view();
428	    }
429	
430	  scope_refresh_view_label();
431	}
432	
433	static void scope_act_pan(int dir)
434	{
435	  uint32_t span = scope_span();
436	  uint32_t maxpan = SCOPE_POINT_CNT - span;
437	  uint32_t step = (maxpan + 7) / 8;
438	
439	  if (step < 1)
440	    {
441	      step = 1;
442	    }
443	
444	  if (dir > 0)
445	    {
446	      /* pan further back into history */
447	
448	      if (g_ui.pan < maxpan)
449	        {
450	          g_ui.pan = g_ui.pan + step;
451	          if (g_ui.pan > maxpan)
452	            {
453	              g_ui.pan = maxpan;
454	            }
455	
456	          scope_apply_view();
457	        }
458	    }
459	  else
460	    {
461	      /* pan back toward the cursor */
462	
463	      if (g_ui.pan >= step)
464	        {
465	          g_ui.pan -= step;
466	        }
467	      else if (g_ui.pan > 0)
468	        {
469	          g_ui.pan = 0;
470	        }
471	
472	      scope_apply_view();
473	    }
474	}
475	
476	static void scope_act_clear(void)
477	{
478	  uint32_t i;
479	
480	  for (i = 0; i < SCOPE_POINT_CNT; i++)
481	    {
482	      lv_chart_set_value_by_id(g_ui.chart_cur, g_ui.ser_id, i, LV_CHART_POINT_NONE);
483	      lv_chart_set_value_by_id(g_ui.chart_cur, g_ui.ser_iq, i, LV_CHART_POINT_NONE);
484	      lv_chart_set_value_by_id(g_ui.chart_rpm, g_ui.ser_rpm, i, LV_CHART_POINT_NONE);
485	    }
486	}
487	
488	static void scope_act_channel(void)
489	{
490	  g_ui.ch_mode = (g_ui.ch_mode + 1) % 3;
491	
492	  lv_chart_hide_series(g_ui.chart_cur, g_ui.ser_id,
493	                       (g_ui.ch_mode != 0 && g_ui.ch_mode != 1));
494	  lv_chart_hide_series(g_ui.chart_cur, g_ui.ser_iq,
495	                       (g_ui.ch_mode != 0 && g_ui.ch_mode != 2));
496	}
497	
498	static void scope_act_scale(void)
499	{
500	  g_ui.scale_idx = (g_ui.scale_idx + 1) % SCALE_MAIN_LEN;
501	
502	  lv_chart_set_range(g_ui.chart_cur, LV_CHART_AXIS_PRIMARY_Y,
503	                     g_scale_main[g_ui.scale_idx][0],
504	                     g_scale_main[g_ui.scale_idx][1]);
505	  lv_chart_set_range(g_ui.chart_rpm, LV_CHART_AXIS_PRIMARY_Y,
506	                     g_scale_rpm[g_ui.scale_idx][0],
507	                     g_scale_rpm[g_ui.scale_idx][1]);
508	
509	  scope_refresh_view_label();
510	}
511	
512	static void scope_btn_cb(lv_event_t *e)
513	{
514	  int act = (int)(intptr_t)lv_event_get_user_data(e);
515	
516	  switch (act)
517	    {
518	      case ACT_PAUSE:
519	        scope_set_state(g_ui.state == SCOPE_STATE_RUN ?
520	                        SCOPE_STATE_PAUSED : SCOPE_STATE_RUN);
521	        break;
522	
523	      case ACT_ZOOM_IN:
524	        scope_act_zoom(1);
525	        break;
526	
527	      case ACT_ZOOM_OUT:
528	        scope_act_zoom(-1);
529	        break;
530	
531	      case ACT_SCALE:
532	        scope_act_scale();
533	        break;
534	
535	      case ACT_CLEAR:
536	        scope_act_clear();
537	        break;
538	
539	      case ACT_LEFT:
540	        scope_act_pan(1);
541	        break;
542	
543	      case ACT_RIGHT:
544	        scope_act_pan(-1);
545	        break;
546	
547	      case ACT_CH:
548	        scope_act_channel();
549	        break;
550	
551	      case ACT_LANG:
552	        g_ui.lang = (g_ui.lang == LANG_ZH) ? LANG_EN : LANG_ZH;
553	        scope_apply_lang();
554	        break;
555	
556	      default:
557	        break;
558	    }
559	}
