561	/* --- data pump --- */
562	
563	static void scope_push_sample(FAR scope_sample_t *s)
564	{
565	  lv_chart_set_next_value(g_ui.chart_cur, g_ui.ser_id,
566	                          (int32_t)(s->id * 1000.0f));
567	  lv_chart_set_next_value(g_ui.chart_cur, g_ui.ser_iq,
568	                          (int32_t)(s->iq * 1000.0f));
569	  lv_chart_set_next_value(g_ui.chart_rpm, g_ui.ser_rpm,
570	                          (int32_t)s->speed);
571	}
572	
573	static void scope_timer_cb(lv_timer_t *timer)
574	{
575	  scope_sample_t s;
576	  int k;
577	
578	  if (g_ui.state == SCOPE_STATE_RUN)
579	    {
580	      for (k = 0; k < SCOPE_SAMPLES_PER_TICK; k++)
581	        {
582	          if (g_ui.ds->get_sample(g_ui.ds, &s) < 0)
583	            {
584	              break;
585	            }
586	
587	          scope_push_sample(&s);
588	          g_ui.last = s;
589	        }
590	    }
591	
592	  /* Readouts refresh every tick (cheap: only the label area redraws) */
593	
594	  lv_label_set_text_fmt(g_ui.lb_id,   "id  %+.2fA", g_ui.last.id);
595	  lv_label_set_text_fmt(g_ui.lb_iq,   "iq  %+.2fA", g_ui.last.iq);
596	  lv_label_set_text_fmt(g_ui.lb_rpm,  "rpm %.0f",   g_ui.last.speed);
597	  lv_label_set_text_fmt(g_ui.lb_vbus, "Vb  %.1fV",  g_ui.last.vbus);
598	}
