27	
28	/* FDCAN1 handle defined in main.c */
29	extern FDCAN_HandleTypeDef hfdcan1;
30	
31	/* High-frequency task rate = PWM_FREQUENCY / REGULATION_EXECUTION_RATE.
32	 * 16 kHz -> 160 ticks per 10 ms. */
33	#define FOC_TEL_TICKS_PER_FRAME   (ISR_FREQUENCY_HZ / 100)
34	
35	static uint16_t s_tel_cnt;
36	
37	/* float A -> int16 mA, clamped to protocol range */
38	static int16_t foc_tel_clamp_i16(float v)
39	{
40	  float mA = v * 1000.0f;
41	
42	  if (mA > 32767.0f)
43	    {
44	      return 32767;
45	    }
46	  if (mA < -32768.0f)
47	    {
48	      return -32768;
49	    }
50	  return (int16_t)mA;
51	}
52	
53	/* Send one 0x501 frame. FIFO full / bus busy -> frame dropped, never blocks. */
54	static void foc_telemetry_send(int16_t id_mA, int16_t iq_mA,
55	                               int16_t speed_rpm, uint16_t vbus_mV)
56	{
57	  FDCAN_TxHeaderTypeDef hdr;
58	  uint8_t d[8];
59	  union { int16_t  s; uint8_t b[2]; } s16;   /* little-endian packing */
60	  union { uint16_t u; uint8_t b[2]; } u16;
61	
62	  s16.s = id_mA;     d[0] = s16.b[0]; d[1] = s16.b[1];
63	  s16.s = iq_mA;     d[2] = s16.b[0]; d[3] = s16.b[1];
64	  s16.s = speed_rpm; d[4] = s16.b[0]; d[5] = s16.b[1];
65	  u16.u = vbus_mV;   d[6] = u16.b[0]; d[7] = u16.b[1];
66	
67	  hdr.Identifier          = 0x501;
68	  hdr.IdType              = FDCAN_STANDARD_ID;
69	  hdr.TxFrameType         = FDCAN_DATA_FRAME;
70	  hdr.DataLength          = FDCAN_DLC_BYTES_8;
71	  hdr.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
72	  hdr.BitRateSwitch       = FDCAN_BRS_OFF;
73	  hdr.FDFormat            = FDCAN_CLASSIC_CAN;
74	  hdr.TxEventFifoControl  = FDCAN_NO_TX_EVENTS;
75	  hdr.MessageMarker       = 0;
76	
77	  (void)HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &hdr, d);
78	}
79	
80	/* Call from TSK_HighFrequencyTask. Sends one frame every 10 ms. */
81	void foc_telemetry_tick(void)
82	{
83	  qd_f_t   iqd;     /* actual id/iq, A (qd order: q first, d second) */
84	  uint16_t vbus_V;  /* average bus voltage, V */
85	
86	  if (++s_tel_cnt < FOC_TEL_TICKS_PER_FRAME)
87	    {
88	      return;
89	    }
90	  s_tel_cnt = 0;
91	
92	  iqd    = MC_GetIqdMotor1_F();
93	  vbus_V = VBS_GetAvBusVoltage_V(&(BusVoltageSensor_M1._Super));
94	
95	  foc_telemetry_send(foc_tel_clamp_i16(iqd.d),      /* id, mA  */
96	                     foc_tel_clamp_i16(iqd.q),      /* iq, mA  */
97	                     SPEED_UNIT_2_RPM(MC_GetMecSpeedAverageMotor1()),
98	                     (uint16_t)((float)vbus_V * 1000.0f));  /* vbus, mV */
99	}
