3	  * @file    foc_telemetry.c
4	  * @brief   FOCPilot CAN telemetry v1 for STM32G4 + MCSDK 6.x.
5	  *
6	  * Frame (classic CAN, 500 kbit/s, standard ID 0x501, 8 bytes little-endian):
7	  *   [0:1] id   int16  mA   (d-axis current)
8	  *   [2:3] iq   int16  mA   (q-axis current)
9	  *   [4:5] rpm  int16  rpm  (mechanical speed)
10	  *   [6:7] vbus uint16 mV   (bus voltage)
11	  *
12	  * 10 ms broadcast, sent even when the motor is stopped (values 0).
13	  * The receiver declares link-lost after 500 ms without frames.
14	  * Protocol: FOCPILOT_CAN_PROTOCOL.md
15	  ******************************************************************************
16	  */
