81	/* Call from TSK_HighFrequencyTask. Sends one frame every 10 ms. */
82	static void foc_tel_dwt_init(void)
83	{
84	  if (s_tel_dwt_on == 0U)
85	    {
86	      CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
87	      DWT->CYCCNT = 0U;
88	      DWT->CTRL  |= DWT_CTRL_CYCCNTENA_Msk;
89	      s_tel_dwt_on = 1U;
90	    }
91	}
92	
93	/* Send one frame every 10 ms. Single call site (main loop), so the link
94	 * stays alive even when the motor is not started. */
95	void foc_telemetry_tick(void)
96	{
97	  qd_f_t   iqd;     /* actual id/iq, A (qd order: q first, d second) */
98	  uint16_t vbus_V;  /* average bus voltage, V */
99	  uint32_t now;
100	
101	  foc_tel_dwt_init();
102	  now = DWT->CYCCNT;
103	
104	  if (now - s_tel_last < (SystemCoreClock / 100U))   /* 10 ms in CPU cycles */
105	    {
106	      return;
107	    }
108	  s_tel_last = now;
109	
110	  iqd    = MC_GetIqdMotor1_F();
111	  vbus_V = VBS_GetAvBusVoltage_V(&(BusVoltageSensor_M1._Super));
112	
113	  foc_telemetry_send(foc_tel_clamp_i16(iqd.d),      /* id, mA  */
114	                     foc_tel_clamp_i16(iqd.q),      /* iq, mA  */
115	                     SPEED_UNIT_2_RPM(MC_GetMecSpeedAverageMotor1()),
116	                     (uint16_t)((float)vbus_V * 1000.0f));  /* vbus, mV */
117	}
