57	 * Description:
58	 *   Grab a boot-lifetime single-instance lock on /tmp (tmpfs, cleared on
59	 *   reboot). On openvela, LVGL's global state lives in per-task TLS, so
60	 *   lv_is_initialized() cannot see another task's LVGL instance: two
61	 *   focscope tasks would both take over /dev/fb0 and /dev/input0 and
62	 *   fight for the screen. A plain O_EXCL file is the reliable guard.
63	 *
64	 ****************************************************************************/
65	
66	static void scope_instance_lock(void)
67	{
68	  char buf[16];
69	  pid_t pid;
70	  ssize_t n;
71	  int fd;
72	  int ofd;
73	
74	  /* Try to take the lock and record our pid in it */
75	
76	  fd = open("/tmp/focscope.lock", O_CREAT | O_EXCL | O_WRONLY, 0666);
77	  if (fd >= 0)
78	    {
79	      dprintf(fd, "%d\n", getpid());
80	      close(fd);
81	      return;
82	    }
83	
84	  if (errno != EEXIST)
85	    {
86	      /* No tmpfs (or some other error): degrade to running unlocked rather
87	       * than refusing to start.  Plain printf: LV_LOG may be lost if the
88	       * task dies before the syslog drain (SYSLOG_BUFFER is small and
89	       * async).
90	       */
91	
