93	      return;
94	    }
95	
96	  /* Another focscope holds the lock (typically the sim instance started
97	   * by xiaozhi.sh at boot).  Identify and terminate it, then take the
98	   * lock.  On openvela LVGL state lives in per-task TLS, so the new
99	   * instance starts a clean LVGL world once the old task is gone.
100	   */
101	
102	  ofd = open("/tmp/focscope.lock", O_RDONLY);
103	  pid = 0;
104	  if (ofd >= 0)
105	    {
