{
  struct scope_can_s *priv = &g_can;

  priv->running = false;
  pthread_cancel(priv->tid);
  pthread_join(priv->tid, NULL);
  if (priv->fd >= 0)
    {
      close(priv->fd);
      priv->fd = -1;
