53	 * while the reader thread is blocked in read() is safe. */
54	
55	#define CANIOC_GET_STATS       _CANIOC(20)
56	
57	struct r528_can_stats_s
58	{
59	  uint32_t isr_cnt;
60	  uint32_t rx_cnt;
61	  uint32_t txdone_cnt;
62	  uint32_t err_printed;
63	  uint32_t isrc_hist[8];
64	  uint32_t isr_last_isrc;
65	  uint32_t isr_last_status;
66	  uint32_t msel;
67	  uint32_t btime;
68	  uint32_t cfg0;
69	};
70	
71	/* Reader thread parameters */
72	
73	#define SCOPE_CAN_STALE_MS     500   /* Link considered lost after this */
74	#define SCOPE_CAN_INIT_TIMEOUT_MS 2000 /* No frame yet since open */
75	
76	/* Main chart is mA: UI multiplies A by 1000, so mA maps 1:1 */
77	
78	/****************************************************************************
79	 * Private Types
80	 ****************************************************************************/
81	
82	struct scope_can_s
83	{
84	  scope_ds_t   ds;
85	  pthread_t    tid;
86	  int          fd;
87	  int          port;        /* 0 = /dev/can0, 1 = /dev/can1 */
88	  bool         running;
89	
90	  pthread_mutex_t lock;
91	  struct timespec t_open;   /* Reader start time */
92	  struct timespec t_last;   /* Last frame arrival */
93	  bool           fresh;     /* A frame arrived since the last get_sample() */
94	  scope_sample_t latest;
95	
96	  /* Frame counters (mutex-guarded, consumed by the link-info page) */
97	
98	  uint32_t nframes_all;     /* every frame received */
99	  uint32_t nframes_501;     /* valid 0x501 frames */
100	  uint32_t nframes_bad;     /* wrong ID or short DLC */
101	};
102	
103	/****************************************************************************
104	 * Private Data
105	 ****************************************************************************/
106	
107	/* focscope is single-instance, so one static source is fine */
108	
109	static struct scope_can_s g_can;
110	static char g_can_name[16];
111	
112	/****************************************************************************
113	 * Private Functions
114	 ****************************************************************************/
115	
116	/****************************************************************************
117	 * Name: scope_can_reader
118	 *
119	 * Description:
120	 *   Blocking CAN reader thread.  Consumes every frame, keeps the latest
121	 *   telemetry sample.
122	 *
123	 ****************************************************************************/
124	
125	static FAR void *scope_can_reader(FAR void *arg)
126	{
127	  struct scope_can_s *priv = (FAR struct scope_can_s *)arg;
128	  struct can_msg_s msg;
129	  scope_sample_t s;
130	  uint32_t raw;
131	  ssize_t nbytes;
132	
133	  while (priv->running)
134	    {
135	      memset(&msg, 0, sizeof(msg));
136	      nbytes = read(priv->fd, &msg, CAN_MSGLEN(SCOPE_CAN_MAX_DLC));
137	      if (nbytes < 0)
138	        {
139	          if (errno == EINTR)
140	            {
141	              continue;
142	            }
143	
144	          /* Device went away (or fatal error): stop the thread */
145	
146	          break;
147	        }
148	
149	      /* Count every frame; only accept our telemetry frame */
150	
151	      if (msg.cm_hdr.ch_id != SCOPE_CAN_ID || msg.cm_hdr.ch_dlc < 8)
152	        {
153	          pthread_mutex_lock(&priv->lock);
154	          priv->nframes_all++;
155	          priv->nframes_bad++;
156	          pthread_mutex_unlock(&priv->lock);
157	          continue;
158	        }
159	
160	      pthread_mutex_lock(&priv->lock);
161	      priv->nframes_all++;
162	      priv->nframes_501++;
163	      pthread_mutex_unlock(&priv->lock);
164	
165	      /* Little-endian decode (match the drive-board implementation) */
166	
167	      raw     = (uint32_t)msg.cm_data[0] | ((uint32_t)msg.cm_data[1] << 8);
168	      s.id    = (float)(int16_t)raw / 1000.0f;
169	
170	      raw     = (uint32_t)msg.cm_data[2] | ((uint32_t)msg.cm_data[3] << 8);
171	      s.iq    = (float)(int16_t)raw / 1000.0f;
172	
173	      raw     = (uint32_t)msg.cm_data[4] | ((uint32_t)msg.cm_data[5] << 8);
174	      s.speed = (float)(int16_t)raw;
175	
176	      raw     = (uint32_t)msg.cm_data[6] | ((uint32_t)msg.cm_data[7] << 8);
177	      s.vbus  = (float)raw / 1000.0f;
178	
179	      pthread_mutex_lock(&priv->lock);
180	      priv->latest = s;
181	      priv->fresh  = true;
182	      clock_gettime(CLOCK_MONOTONIC, &priv->t_last);
183	      pthread_mutex_unlock(&priv->lock);
184	    }
185	
186	  return NULL;
187	}
188	
189	/****************************************************************************
190	 * Name: scope_can_elapsed_ms
191	 *
192	 * Description:
193	 *   Milliseconds elapsed between a and b (a >= b).
194	 *
195	 ****************************************************************************/
196	
197	static int64_t scope_can_elapsed_ms(FAR const struct timespec *a,
198	                                    FAR const struct timespec *b)
199	{
200	  return (int64_t)(a->tv_sec - b->tv_sec) * 1000 +
201	         (a->tv_nsec - b->tv_nsec) / 1000000;
202	}
203	
204	/****************************************************************************
205	 * Public Functions
206	 ****************************************************************************/
207	
208	/****************************************************************************
209	 * Name: scope_ds_can_init
210	 *
211	 ****************************************************************************/
212	
213	static int scope_ds_can_init(FAR scope_ds_t *ds)
214	{
215	  struct scope_can_s *priv = &g_can;
216	  char path[16];
217	  int ret;
218	
219	  snprintf(path, sizeof(path), "/dev/can%d", priv->port);
220	
221	  priv->fd = open(path, O_RDONLY);
222	  if (priv->fd < 0)
223	    {
224	      fprintf(stderr, "scope_can: open %s failed: %d\n", path, errno);
225	      return -1;
226	    }
227	
228	  pthread_mutex_init(&priv->lock, NULL);
229	  clock_gettime(CLOCK_MONOTONIC, &priv->t_open);
230	  priv->t_last = priv->t_open;
231	  priv->fresh  = false;
232	  memset(&priv->latest, 0, sizeof(priv->latest));
233	  priv->running = true;
234	
235	  ret = pthread_create(&priv->tid, NULL, scope_can_reader, priv);
236	  if (ret != 0)
237	    {
238	      fprintf(stderr, "scope_can: thread create failed: %d\n", ret);
239	      close(priv->fd);
240	      priv->fd = -1;
241	      priv->running = false;
242	      return -1;
243	    }
244	
245	  return 0;
246	}
247	
248	/****************************************************************************
249	 * Name: scope_ds_can_deinit
250	 *
251	 ****************************************************************************/
252	
253	static void scope_ds_can_deinit(FAR scope_ds_t *ds)
254	{
255	  struct scope_can_s *priv = &g_can;
256	
257	  priv->running = false;
258	  pthread_cancel(priv->tid);
259	  pthread_join(priv->tid, NULL);
260	  if (priv->fd >= 0)
261	    {
262	      close(priv->fd);
263	      priv->fd = -1;
264	    }
265	
266	  pthread_mutex_destroy(&priv->lock);
267	}
268	
269	/****************************************************************************
270	 * Name: scope_ds_can_get_sample
271	 *
272	 * Description:
273	 *   Return the latest telemetry sample.  Never blocks (the reader thread
274	 *   does the I/O).  Reports an error when no frame has arrived for
275	 *   SCOPE_CAN_STALE_MS (link lost) so the UI stops the traces; normal
276	 *   operation resumes automatically.
277	 *
278	 ****************************************************************************/
279	
280	static int scope_ds_can_get_sample(FAR scope_ds_t *ds, FAR scope_sample_t *s)
281	{
282	  struct scope_can_s *priv = &g_can;
283	  struct timespec now;
284	  int64_t since_last;
285	  int64_t since_open;
286	
287	  clock_gettime(CLOCK_MONOTONIC, &now);
288	
289	  pthread_mutex_lock(&priv->lock);
290	  since_last = scope_can_elapsed_ms(&now, &priv->t_last);
291	  since_open = scope_can_elapsed_ms(&now, &priv->t_open);
292	
293	  if ((!priv->fresh && since_last > SCOPE_CAN_STALE_MS) ||
294	      (!priv->fresh && since_open > SCOPE_CAN_INIT_TIMEOUT_MS))
295	    {
296	      pthread_mutex_unlock(&priv->lock);
297	      return -1;
298	    }
299	
300	  *s = priv->latest;
301	  priv->fresh = false;
302	  pthread_mutex_unlock(&priv->lock);
303	
304	  return 0;
305	}
306	
307	/****************************************************************************
308	 * Name: scope_ds_can_get_stats
309	 *
310	 * Description:
311	 *   Fill the CAN link statistics for the UI link-info page.  Fast and
312	 *   non-blocking: app-level counters come from the mutex-guarded reader
313	 *   state, driver-level counters from the read-only stats ioctl.
314	 *
315	 ****************************************************************************/
316	
317	static int scope_ds_can_get_stats(FAR scope_ds_t *ds,
318	                                  FAR scope_can_stats_t *st)
319	{
320	  struct scope_can_s *priv = &g_can;
321	  struct r528_can_stats_s hw;
322	  struct timespec now;
323	
324	  memset(st, 0, sizeof(*st));
325	
326	  pthread_mutex_lock(&priv->lock);
327	  st->nframes_all = priv->nframes_all;
328	  st->nframes_501 = priv->nframes_501;
329	  st->nframes_bad = priv->nframes_bad;
330	  pthread_mutex_unlock(&priv->lock);
331	
332	  clock_gettime(CLOCK_MONOTONIC, &now);
333	  st->last_age_ms = (int32_t)scope_can_elapsed_ms(&now, &priv->t_last);
334	  if (priv->nframes_501 == 0)
335	    {
336	      st->last_age_ms = -1;   /* nothing received yet */
337	    }
338	
339	  if (priv->fd >= 0 &&
340	      ioctl(priv->fd, CANIOC_GET_STATS, (unsigned long)&hw) == 0)
341	    {
342	      st->isr_cnt         = hw.isr_cnt;
343	      st->rx_cnt          = hw.rx_cnt;
344	      st->txdone_cnt      = hw.txdone_cnt;
345	      st->isr_last_isrc   = hw.isr_last_isrc;
346	      st->isr_last_status = hw.isr_last_status;
347	      st->msel            = hw.msel;
348	      st->btime           = hw.btime;
349	    }
350	
351	  return 0;
352	}
353	
354	/****************************************************************************
355	 * Name: scope_ds_can_get
356	 *
357	 * Description:
358	 *   Factory: CAN-backed data source.  The device path is compile-time
359	 *   fixed to /dev/can0 for now.
360	 *
361	 ****************************************************************************/
362	
363	scope_ds_t scope_ds_can_get(int port)
364	{
365	  memset(&g_can, 0, sizeof(g_can));
366	  g_can.fd = -1;
367	  g_can.port = port;
368	
369	  snprintf(g_can_name, sizeof(g_can_name), "CAN%d 0x501", port);
370	
371	  g_can.ds.name          = g_can_name;
372	  g_can.ds.init          = scope_ds_can_init;
373	  g_can.ds.deinit        = scope_ds_can_deinit;
374	  g_can.ds.get_sample    = scope_ds_can_get_sample;
375	  g_can.ds.get_can_stats = scope_ds_can_get_stats;
376	
377	  return g_can.ds;
378	}
