1	/****************************************************************************
2	 * apps/examples/focscope/scope_ui.c
3	 *
4	 * FOCPilot oscilloscope UI.
5	 *
6	 * Layout (320x480 portrait):
7	 *   title bar  (y=6)      title + [EN/中文 toggle][state]
8	 *   main chart (4,34)     312x202  id/iq current, mA
9	 *   rpm chart  (4,238)    312x94   speed, rpm
10	 *   readouts   (y=336)    id / iq / rpm / Vb live values
11	 *   buttons r1 (y=376)    PAUSE  ZOOM+  ZOOM-  SCALE
12	 *   buttons r2 (y=428)    CLEAR  <      >      CH
13	 *
14	 * Language: all user-visible strings live in one table (g_lang, zh + en).
15	 * The top-right button toggles the active language and re-texts every
16	 * label from that table. The full-Unicode 20px PuHui font (from
17	 * lvgldemo's font_puhui_20_4.c) covers both scripts.
18	 *
19	 * Behavior:
20	 *   - Data is polled from the scope_ds_t source in a 50 ms lv_timer
21	 *     callback (single-threaded; all LVGL calls happen inside
22	 *     lv_timer_handler()).
23	 *   - RUN: values scroll in (SHIFT mode). ZOOM+/ZOOM- (horizontal zoom /
24	 *     time base) and SCALE (vertical range) work live; a small label over
25	 *     the main chart shows the current time span and range, so the
26	 *     adjustments are visible while running.
27	 *   - PAUSED: the write cursor is frozen; ZOOM+/- and SCALE keep working,
28	 *     and < / > (pan) plus CLEAR become available.
29	 *   - CH cycles id/iq visibility.
30	 *
31	 * NOTE on v9.1 chart semantics (verified against lv_chart.c):
32	 *   - lv_chart_get_x_start_point() only returns ser->start_point in
33	 *     SHIFT mode; CIRCULAR mode ignores panning.
34	 *   - lv_chart_set_x_start_point() is per-series - set every series.
35	 *   - set_next_value() advances ser->start_point; never touch
36	 *     x_start_point while running.
37	 *   - Zoomed drawing maps point window [start, start+span) onto the
38	 *     content width, span = point_cnt * 256 / zoom_x.
39	 *
40	 ****************************************************************************/
41	
