314	/* Visible span in samples for the current zoom */
315	
316	static uint32_t scope_span(void)
317	{
318	  return (SCOPE_POINT_CNT * 256 + g_ui.zoom / 2) / g_ui.zoom;
319	}
320	
321	/* Apply the current zoom/pan window to every series of both charts.
322	 * Window end is anchored at the frozen cursor; pan moves it back. */
323	
324	static void scope_apply_view(void)
325	{
326	  uint32_t span = scope_span();
327	  uint32_t maxpan = SCOPE_POINT_CNT - span;
328	  uint32_t pan = g_ui.pan;
329	  uint32_t start;
330	
331	  if (pan > maxpan)
332	    {
333	      pan = maxpan;
334	      g_ui.pan = pan;
335	    }
336	
337	  start = (g_ui.cursor + SCOPE_POINT_CNT - span - pan) % SCOPE_POINT_CNT;
338	
339	  /* Per-series: every series of every chart sharing the time base */
340	
341	  lv_chart_set_x_start_point(g_ui.chart_cur, g_ui.ser_id, start);
342	  lv_chart_set_x_start_point(g_ui.chart_cur, g_ui.ser_iq, start);
343	  lv_chart_set_x_start_point(g_ui.chart_rpm, g_ui.ser_rpm, start);
344	}
