346	static void scope_set_zoom(uint32_t zoom)
347	{
348	  g_ui.zoom = zoom;
349	  lv_chart_set_zoom_x(g_ui.chart_cur, zoom);
350	  lv_chart_set_zoom_x(g_ui.chart_rpm, zoom);
351	}
