404	                    g_ui.state == SCOPE_STATE_RUN ?
405	                    l->state_run : l->state_paused);
406	
407	  for (i = 0; i < 9; i++)
408	    {
409	      lv_label_set_text(g_ui.lab_btn[i], l->btn[i]);
410	    }
411	
412	  /* The CAN button doubles as BACK while the CAN page is shown */
