418	static void scope_set_state(scope_state_t state)
419	{
420	  g_ui.state = state;
421	
422	  if (state == SCOPE_STATE_RUN)
423	    {
424	      /* Resume following the live cursor.  Keep the current zoom (the
425	       * user may have set it while running); only clear the pan - the
426	       * SHIFT window re-anchors itself at the newest samples.
427	       */
428	
429	      g_ui.pan = 0;
430	      scope_refresh_view_label();
431	      lv_obj_set_style_text_color(g_ui.lb_state, CLR_RUN, 0);
432	    }
433	  else
434	    {
435	      /* Freeze the write cursor as the window anchor */
436	
437	      g_ui.cursor = lv_chart_get_x_start_point(g_ui.chart_cur, g_ui.ser_id);
438	      g_ui.pan = 0;
439	      scope_apply_view();
440	      scope_refresh_view_label();
441	      lv_obj_set_style_text_color(g_ui.lb_state, CLR_PAUSED, 0);
442	    }
443	
444	  scope_apply_lang();
445	  scope_set_view_btns_enabled(state == SCOPE_STATE_PAUSED);
446	}
