448	/* --- button actions --- */
449	
450	static void scope_act_zoom(int dir)
451	{
452	  int i;
453	  int idx = -1;
454	
455	  for (i = 0; i < (int)ZOOM_TABLE_LEN; i++)
456	    {
457	      if (g_zoom_table[i] == g_ui.zoom)
458	        {
459	          idx = i;
460	          break;
461	        }
462	    }
463	
464	  if (idx < 0)
465	    {
466	      idx = 0;
467	    }
468	
469	  idx += dir;
470	  if (idx < 0 || idx >= (int)ZOOM_TABLE_LEN)
471	    {
472	      return;
473	    }
474	
475	  scope_set_zoom(g_zoom_table[idx]);
476	
477	  /* In RUN the SHIFT window follows the live cursor by itself; only the
478	   * paused view needs re-anchoring at the frozen cursor.
479	   */
480	
481	  if (g_ui.state == SCOPE_STATE_PAUSED)
482	    {
483	      scope_apply_view();
484	    }
485	
486	  scope_refresh_view_label();
487	}
488	
489	static void scope_act_pan(int dir)
490	{
491	  uint32_t span = scope_span();
492	  uint32_t maxpan = SCOPE_POINT_CNT - span;
493	  uint32_t step = (maxpan + 7) / 8;
494	
495	  if (step < 1)
496	    {
497	      step = 1;
498	    }
499	
500	  if (dir > 0)
501	    {
502	      /* pan further back into history */
503	
504	      if (g_ui.pan < maxpan)
505	        {
506	          g_ui.pan = g_ui.pan + step;
507	          if (g_ui.pan > maxpan)
508	            {
509	              g_ui.pan = maxpan;
510	            }
511	
512	          scope_apply_view();
513	        }
514	    }
515	  else
516	    {
517	      /* pan back toward the cursor */
518	
519	      if (g_ui.pan >= step)
520	        {
521	          g_ui.pan -= step;
522	        }
523	      else if (g_ui.pan > 0)
524	        {
525	          g_ui.pan = 0;
526	        }
527	
528	      scope_apply_view();
529	    }
530	}
