622	/* Refresh the CAN page contents. Called every tick while the page is
623	 * shown (cheap: a few label re-texts, only the page area redraws). */
624	
625	static void scope_refresh_can_page(void)
626	{
627	  const struct scope_lang_s *l = &g_lang[g_ui.lang];
628	  scope_can_stats_t st;
629	  uint32_t now;
630	  uint32_t dt;
631	  uint32_t dframes;
632	
633	  if (g_ui.ds->get_can_stats == NULL)
634	    {
635	      lv_label_set_text(g_ui.lb_can_link, l->can_no);
636	      return;
637	    }
638	
639	  if (g_ui.ds->get_can_stats(g_ui.ds, &st) < 0)
640	    {
641	      return;
642	    }
643	
644	  /* Link state: LOST once no frame for SCOPE_CAN_STALE_MS */
645	
646	  if (st.last_age_ms >= 0 && st.last_age_ms < SCOPE_CAN_STALE_MS)
647	    {
648	      lv_obj_set_style_text_color(g_ui.lb_can_link, CLR_RUN, 0);
649	      lv_label_set_text_fmt(g_ui.lb_can_link, "%s  %lu",
650	                            l->can_link_ok,
651	                            (unsigned long)st.nframes_501);
652	    }
653	  else
654	    {
655	      lv_obj_set_style_text_color(g_ui.lb_can_link, CLR_PAUSED, 0);
656	      if (st.last_age_ms < 0)
657	        {
658	          lv_label_set_text(g_ui.lb_can_link, l->can_link_lost);
659	        }
660	      else
661	        {
662	          lv_label_set_text_fmt(g_ui.lb_can_link, "%s  %.1fs",
663	                                l->can_link_lost,
664	                                (double)(st.last_age_ms / 1000.0));
665	        }
666	    }
667	
668	  /* Frame-rate estimate: 500 ms sliding window */
669	
670	  now = lv_tick_get();
671	  dt = now - g_ui.fr_tick;
672	  if (dt >= 500)
673	    {
674	      dframes = st.nframes_501 - g_ui.fr_nframes;
675	      g_ui.fr_hz = (dframes * 1000) / dt;
676	      g_ui.fr_nframes = st.nframes_501;
677	      g_ui.fr_tick = now;
678	    }
679	
680	  lv_label_set_text_fmt(g_ui.lb_can_frames, "%s %lu    %s %luHz    %s %lu",
681	                        l->can_frames, (unsigned long)st.nframes_501,
682	                        l->can_rate, (unsigned long)g_ui.fr_hz,
683	                        l->can_bad, (unsigned long)st.nframes_bad);
684	
685	  lv_label_set_text_fmt(g_ui.lb_can_val,
686	                        "id %+.2fA   iq %+.2fA\n"
687	                        "rpm %.0f   Vb %.1fV\n"
688	                        "%s %lu",
689	                        g_ui.last.id, g_ui.last.iq,
690	                        g_ui.last.speed, g_ui.last.vbus,
691	                        l->can_title, (unsigned long)st.nframes_all);
692	
693	  lv_label_set_text_fmt(g_ui.lb_can_hw,
694	                        "%s\n"
695	                        "ISR %lu  RX %lu  TX %lu\n"
696	                        "STA 0x%lx  ISRC 0x%lx\n"
697	                        "MSEL 0x%lx  BTIME 0x%lx",
698	                        l->can_hw,
699	                        (unsigned long)st.isr_cnt,
700	                        (unsigned long)st.rx_cnt,
701	                        (unsigned long)st.txdone_cnt,
702	                        (unsigned long)st.isr_last_status,
703	                        (unsigned long)st.isr_last_isrc,
704	                        (unsigned long)st.msel,
705	                        (unsigned long)st.btime);
706	}
