748	static void scope_btn_cb(lv_event_t *e)
749	{
750	  int act = (int)(intptr_t)lv_event_get_user_data(e);
751	
752	  switch (act)
753	    {
754	      case ACT_PAUSE:
755	        scope_set_state(g_ui.state == SCOPE_STATE_RUN ?
756	                        SCOPE_STATE_PAUSED : SCOPE_STATE_RUN);
757	        break;
758	
759	      case ACT_ZOOM_IN:
760	        scope_act_zoom(1);
761	        break;
762	
763	      case ACT_ZOOM_OUT:
764	        scope_act_zoom(-1);
765	        break;
766	
767	      case ACT_SCALE:
768	        scope_act_scale();
769	        break;
770	
771	      case ACT_CLEAR:
772	        scope_act_clear();
773	        break;
774	
775	      case ACT_LEFT:
776	        scope_act_pan(1);
777	        break;
778	
779	      case ACT_RIGHT:
780	        scope_act_pan(-1);
781	        break;
782	
783	      case ACT_CH:
784	        scope_act_channel();
785	        break;
786	
787	      case ACT_CAN:
788	        scope_act_can();
789	        break;
790	
791	      case ACT_LANG:
792	        g_ui.lang = (g_ui.lang == LANG_ZH) ? LANG_EN : LANG_ZH;
793	        scope_apply_lang();
794	        break;
795	
796	      default:
797	        break;
798	    }
799	}
