1	/**
2	  ******************************************************************************
3	  * @file    foc_telemetry.c
4	  * @brief   FOCPilot CAN telemetry v1 for STM32G4 + MCSDK 6.x.
5	  *
6	  * Frame (classic CAN, 500 kbit/s, standard ID 0x501, 8 bytes little-endian):
7	  *   [0:1] id   int16  mA   (d-axis current)
8	  *   [2:3] iq   int16  mA   (q-axis current)
9	  *   [4:5] rpm  int16  rpm  (mechanical speed)
10	  *   [6:7] vbus uint16 mV   (bus voltage)
11	  *
12	  * 10 ms broadcast, sent even when the motor is stopped (values 0).
13	  * The receiver declares link-lost after 500 ms without frames.
14	  * Protocol: FOCPILOT_CAN_PROTOCOL.md
15	  ******************************************************************************
16	  */
17	
18	#include <string.h>
19	
20	#include "main.h"
21	#include "drive_parameters.h"
22	#include "mc_api.h"
23	#include "mc_stm_types.h"
24	#include "mc_config_common.h"
25	#include "bus_voltage_sensor.h"
26	#include "foc_telemetry.h"
27	
28	/* FDCAN1 handle defined in main.c */
29	extern FDCAN_HandleTypeDef hfdcan1;
30	
31	/* 10 ms frame period, measured with the DWT cycle counter (free-running CPU
32	 * cycle counter). Unlike HAL_GetTick() it needs no interrupt, so it keeps
33	 * counting even when SysTick is starved by the FOC interrupts (SysTick has
34	 * priority 4 here, below ADC1_2 = 2 and TIM1_UP = 0). */
35	static uint32_t s_tel_last;   /* last send time, in CPU cycles */
36	static uint8_t  s_tel_dwt_on; /* DWT cycle counter enabled */
37	
38	/* float A -> int16 mA, clamped to protocol range */
39	static int16_t foc_tel_clamp_i16(float v)
40	{
41	  float mA = v * 1000.0f;
42	
43	  if (mA > 32767.0f)
44	    {
45	      return 32767;
46	    }
47	  if (mA < -32768.0f)
48	    {
49	      return -32768;
50	    }
51	  return (int16_t)mA;
52	}
53	
54	/* Send one 0x501 frame. FIFO full / bus busy -> frame dropped, never blocks. */
55	static void foc_telemetry_send(int16_t id_mA, int16_t iq_mA,
56	                               int16_t speed_rpm, uint16_t vbus_mV)
57	{
58	  FDCAN_TxHeaderTypeDef hdr;
59	  uint8_t d[8];
60	  union { int16_t  s; uint8_t b[2]; } s16;   /* little-endian packing */
61	  union { uint16_t u; uint8_t b[2]; } u16;
62	
63	  s16.s = id_mA;     d[0] = s16.b[0]; d[1] = s16.b[1];
64	  s16.s = iq_mA;     d[2] = s16.b[0]; d[3] = s16.b[1];
65	  s16.s = speed_rpm; d[4] = s16.b[0]; d[5] = s16.b[1];
66	  u16.u = vbus_mV;   d[6] = u16.b[0]; d[7] = u16.b[1];
67	
68	  hdr.Identifier          = 0x501;
69	  hdr.IdType              = FDCAN_STANDARD_ID;
70	  hdr.TxFrameType         = FDCAN_DATA_FRAME;
71	  hdr.DataLength          = FDCAN_DLC_BYTES_8;
72	  hdr.ErrorStateIndicator = FDCAN_ESI_ACTIVE;
73	  hdr.BitRateSwitch       = FDCAN_BRS_OFF;
74	  hdr.FDFormat            = FDCAN_CLASSIC_CAN;
75	  hdr.TxEventFifoControl  = FDCAN_NO_TX_EVENTS;
76	  hdr.MessageMarker       = 0;
77	
78	  (void)HAL_FDCAN_AddMessageToTxFifoQ(&hfdcan1, &hdr, d);
79	}
80	
81	/* Call from TSK_HighFrequencyTask. Sends one frame every 10 ms. */
82	static void foc_tel_dwt_init(void)
83	{
84	  if (s_tel_dwt_on == 0U)
85	    {
86	      CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
87	      DWT->CYCCNT = 0U;
88	      DWT->CTRL  |= DWT_CTRL_CYCCNTENA_Msk;
89	      s_tel_dwt_on = 1U;
90	    }
91	}
92	
93	/* Send one frame every 10 ms. Single call site (main loop), so the link
94	 * stays alive even when the motor is not started. */
95	void foc_telemetry_tick(void)
96	{
97	  qd_f_t   iqd;     /* actual id/iq, A (qd order: q first, d second) */
98	  uint16_t vbus_V;  /* average bus voltage, V */
99	  uint32_t now;
100	
101	  foc_tel_dwt_init();
102	  now = DWT->CYCCNT;
103	
104	  if (now - s_tel_last < (SystemCoreClock / 100U))   /* 10 ms in CPU cycles */
105	    {
106	      return;
107	    }
108	  s_tel_last = now;
109	
110	  iqd    = MC_GetIqdMotor1_F();
111	  vbus_V = VBS_GetAvBusVoltage_V(&(BusVoltageSensor_M1._Super));
112	
113	  foc_telemetry_send(foc_tel_clamp_i16(iqd.d),      /* id, mA  */
114	                     foc_tel_clamp_i16(iqd.q),      /* iq, mA  */
115	                     SPEED_UNIT_2_RPM(MC_GetMecSpeedAverageMotor1()),
116	                     (uint16_t)((float)vbus_V * 1000.0f));  /* vbus, mV */
117	}
