414:/* 256-entry int16 sine table, amplitude 32767 */
416:static const int16_t g_sine[256] =
460:#define CANTEST_BCAST_ID        0x501   /* protocol v1 telemetry frame ID */
464:static void cantest_bcast_frame(uint32_t *phase_id, uint32_t *phase_rpm,
469:  /* id: 0.5 Hz sine, +/-2500 mA; iq: same frequency, 90 deg behind */
471:  v = (int32_t)g_sine[(*phase_id >> 16) & 0xff] * 2500 / 32767;
475:  v = (int32_t)g_sine[((*phase_id >> 16) + 64) & 0xff] * 2200 / 32767;
481:  v = 1600 + (int32_t)g_sine[(*phase_rpm >> 16) & 0xff] * 500 / 32767;
487:  v = 24000 + (int32_t)g_sine[(*phase_vbus >> 16) & 0xff] * 400 / 32767;
497: * Name: cantest_bcast
501: *   (ID 0x501, 8 data bytes little-endian, 10 ms cadence) on the given
509:static int cantest_bcast(FAR const char *devname)
521:  printf("cantest: bcast: open ret=%d errno=%d\n", fd, errno);
528:  printf("cantest: bcast: 0x%03x @50Hz on %s (fake drive board)\n",
536:      cantest_bcast_frame(&phase_id, &phase_rpm, &phase_vbus, msg.cm_data);
541:          fprintf(stderr, "cantest: bcast: write failed: %d\n", errno);
549:          printf("cantest: bcast: t=%lus frames=%lu\n",
596:      if (strcmp(argv[1], "bcast") == 0)
598:          printf("cantest: %s bcast mode start\n",
600:          return cantest_bcast(port == 0 ? "/dev/can0" : "/dev/can1") == 0 ?
604:      fprintf(stderr, "usage: cantest [send|recv|bcast] [0|1]\n");

static void cantest_bcast_frame(uint32_t *phase_id, uint32_t *phase_rpm,
                                uint32_t *phase_vbus, FAR uint8_t *d)
{
  int32_t v;

  /* id: 0.5 Hz sine, +/-2500 mA; iq: same frequency, 90 deg behind */

  v = (int32_t)g_sine[(*phase_id >> 16) & 0xff] * 2500 / 32767;
  d[0] = (uint8_t)(v & 0xff);
  d[1] = (uint8_t)((v >> 8) & 0xff);

  v = (int32_t)g_sine[((*phase_id >> 16) + 64) & 0xff] * 2200 / 32767;
  d[2] = (uint8_t)(v & 0xff);
  d[3] = (uint8_t)((v >> 8) & 0xff);

  /* rpm: slow beat around 1600 (UI range 0..3000) */

  v = 1600 + (int32_t)g_sine[(*phase_rpm >> 16) & 0xff] * 500 / 32767;
  d[4] = (uint8_t)(v & 0xff);
  d[5] = (uint8_t)((v >> 8) & 0xff);

  /* vbus: 24.0 V + 2 Hz ripple of +-0.4 V */

  v = 24000 + (int32_t)g_sine[(*phase_vbus >> 16) & 0xff] * 400 / 32767;
  d[6] = (uint8_t)(v & 0xff);
  d[7] = (uint8_t)((v >> 8) & 0xff);

  *phase_id  += CANTEST_BCAST_STEP_IDIQ;
  *phase_rpm += CANTEST_BCAST_STEP_RPM;
  *phase_vbus += CANTEST_BCAST_STEP_VBUS;
}

