/* 0x502 frame: bus current, uint16 mA, 1.5 A base + 0.5 A ripple */

static void cantest_bcast_ibus_frame(uint32_t *phase_ibus, FAR uint8_t *d)
{
  int32_t v;

  v = 1500 + (int32_t)g_sine[(*phase_ibus >> 16) & 0xff] * 500 / 32767;
  d[0] = (uint8_t)(v & 0xff);
  d[1] = (uint8_t)((v >> 8) & 0xff);
  d[2] = d[3] = d[4] = d[5] = d[6] = d[7] = 0;   /* reserved */

  *phase_ibus += CANTEST_BCAST_STEP_IBUS;
}

