That's the cleanest for their codebase — all APIs they already use. I'll provide:

```c
/* 母线电流估算(无专用母线电流传感器):P=1.5*(vd*id+vq*iq),ibus=P/vbus */
static uint16_t foc_tel_ibus_mA(qd_f_t iqd, qd_t vqd, uint16_t vbus_V)
{
  float p = 1.5f * (vqd.d * iqd.d + vqd.q * iqd.q);   /* W */
  float ib = p / (float)vbus_V;                        /* A */
  if (ib < 0.0f) ib = 0.0f;
  if (ib > 65.535f) ib = 65.535f;
  return (uint16_t)(ib * 1000.0f);
}
