/* 0x502 frame: bus current, uint16 mA, 1.5 A base + 0.5 A ripple */

static void cantest_bcast_ibus_frame(uint32_t *phase_ibus, FAR uint8_t *d)
{
  int32_t v;

  v = 1500 + (int32_t)g_sine[(*phase_ibus >> 16) & 0xff] * 500 / 32767;
  d[0] = (uint8_t)(v & 0xff);
  d[1] = (uint8_t)((v >> 8) & 0xff);
  d[2] = d[3] = d[4] = d[5] = d[6] = d[7] = 0;   /* reserved */

  *phase_ibus += CANTEST_BCAST_STEP_IBUS;
}

/****************************************************************************
 * Name: cantest_bcast
 *
 * Description:
 *   Fake drive-board mode: broadcast FOCPILOT CAN protocol v1 telemetry
 *   (ID 0x501 waveform + 0x502 bus current, 8 data bytes little-endian,
 *   10 ms cadence) on the given port.  Lets `focscope can` be exercised
 *   against a live 100 Hz stream - protocol decode, waveform rendering and
 *   the 500 ms stale-link detection - without the real drive board.
 *   Runs forever; stop with nsh `kill <pid>` or reboot.
 *
 ****************************************************************************/

static int cantest_bcast(FAR const char *devname)
{
  struct can_msg_s msg;
  uint32_t phase_id = 0;
  uint32_t phase_rpm = 0;
  uint32_t phase_vbus = 0;
  uint32_t phase_ibus = 0;
  uint32_t nframes = 0;
  ssize_t nbytes;
  int fd;
  int i;

  fd = open(devname, O_WRONLY);
  printf("cantest: bcast: open ret=%d errno=%d\n", fd, errno);
  if (fd < 0)
    {
      fprintf(stderr, "cantest: open %s failed: %d\n", devname, errno);
      return -1;
    }

  printf("cantest: bcast: 0x%03x+0x%03x @100Hz on %s (fake drive board)\n",
         CANTEST_BCAST_ID, CANTEST_BCAST_ID_IBUS, devname);

  for (; ; )
    {
      /* 0x501: waveform telemetry */

      memset(&msg, 0, sizeof(msg));
      msg.cm_hdr.ch_id  = CANTEST_BCAST_ID;
      msg.cm_hdr.ch_dlc = 8;
      cantest_bcast_frame(&phase_id, &phase_rpm, &phase_vbus, msg.cm_data);

      nbytes = write(fd, &msg, CAN_MSGLEN(msg.cm_hdr.ch_dlc));
      if (nbytes < 0)
        {
          fprintf(stderr, "cantest: bcast: write failed: %d\n", errno);
          close(fd);
          return -1;
        }

      /* 0x502: bus current, same cadence */

      memset(&msg, 0, sizeof(msg));
      msg.cm_hdr.ch_id  = CANTEST_BCAST_ID_IBUS;
      msg.cm_hdr.ch_dlc = 8;
      cantest_bcast_ibus_frame(&phase_ibus, msg.cm_data);

